use std::ffi::{CStr, CString};
use std::os::raw::{c_char, c_int, c_void};

#[link(name = "sqlite3")]
extern "C" {
    fn sqlite3_open(filename: *const c_char, ppDb: *mut *mut c_void) -> c_int;
    fn sqlite3_close(db: *mut c_void) -> c_int;
    fn sqlite3_exec(
        db: *mut c_void,
        sql: *const c_char,
        callback: Option<extern "C" fn(*mut c_void, c_int, *mut *mut c_char, *mut *mut c_char) -> c_int>,
        arg: *mut c_void,
        errmsg: *mut *mut c_char,
    ) -> c_int;
    fn sqlite3_errmsg(db: *mut c_void) -> *const c_char;
}

fn main() {
    let path = CString::new("/tmp/test_ffi.db").unwrap();
    let mut db: *mut c_void = std::ptr::null_mut();
    unsafe {
        let rc = sqlite3_open(path.as_ptr(), &mut db);
        assert_eq!(rc, 0);
        let sql = CString::new("CREATE TABLE IF NOT EXISTS test (id INT);").unwrap();
        let rc = sqlite3_exec(db, sql.as_ptr(), None, std::ptr::null_mut(), std::ptr::null_mut());
        assert_eq!(rc, 0);
        sqlite3_close(db);
    }
    println!("SQLite FFI works successfully!");
}
EOF

