{"command":"cat <<'EOF' > src/logging.rs
use std::fs::OpenOptions;
use std::io::Write;
use std::path::Path;
use std::sync::Mutex;
use chrono::Local;

static LOG_FILE: Mutex<Option<std::fs::File>> = Mutex::new(None);
static LOG_LEVEL: Mutex<u8> = Mutex::new(0);

pub fn init_logging(log_path: &Path, verbosity: u8) {
    if let Some(parent) = log_path.parent() {
        let _ = std::fs::create_dir_all(parent);
    }
    if let Ok(file) = OpenOptions::new().create(true).append(true).open(log_path) {
        if let Ok(mut guard) = LOG_FILE.lock() {
            *guard = Some(file);
        }
    }
    if let Ok(mut guard) = LOG_LEVEL.lock() {
        *guard = verbosity;
    }
    let level_str = match verbosity {
        0 => "WARN",
        1 => "INFO",
        2 => "DEBUG",
        _ => "TRACE",
    };
    log_msg(&format!("Log initialized with level: {}", level_str), "TRACE");
}

pub fn log_msg(msg: &str, level: &str) {
    let now = Local::now().format("%H:%M:%S");
    let line = format!("{} [{}] {}\n", now, level, msg);
    if let Ok(mut guard) = LOG_FILE.lock() {
        if let Some(ref mut file) = *guard {
            let _ = file.write_all(line.as_bytes());
        }
    }
}
EOF"}

