use serde::{Deserialize, Serialize};
use std::path::{Path, PathBuf};

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum BackendType {
    Json,
    Sqlite,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum DatumVisibility {
    Show,
    Hide,
    EmptyLine,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ExportConfig {
    pub show_confirmation: bool,
}

impl Default for ExportConfig {
    fn default() -> Self {
        Self {
            show_confirmation: true,
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ExternalEditorConfig {
    #[serde(skip_serializing_if = "Option::is_none")]
    pub command: Option<String>,
    pub auto_save: bool,
    pub temp_file_extension: String,
}

impl Default for ExternalEditorConfig {
    fn default() -> Self {
        Self {
            command: None,
            auto_save: false,
            temp_file_extension: "txt".to_string(),
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct JsonBackendConfig {
    pub file_path: PathBuf,
}

impl Default for JsonBackendConfig {
    fn default() -> Self {
        let home = dirs::home_dir().unwrap_or_else(|| PathBuf::from("/home/agent"));
        Self {
            file_path: home.join("tui-journal/entries.json"),
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SqliteBackendConfig {
    pub file_path: PathBuf,
}

impl Default for SqliteBackendConfig {
    fn default() -> Self {
        let home = dirs::home_dir().unwrap_or_else(|| PathBuf::from("/home/agent"));
        Self {
            file_path: home.join("tui-journal/entries.db"),
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Config {
    pub backend_type: BackendType,
    pub scroll_per_page: usize,
    pub sync_os_clipboard: bool,
    pub history_limit: usize,
    pub colored_tags: bool,
    pub datum_visibility: DatumVisibility,
    pub app_state_dir: PathBuf,
    pub export: ExportConfig,
    pub external_editor: ExternalEditorConfig,
    pub json_backend: JsonBackendConfig,
    pub sqlite_backend: SqliteBackendConfig,
}

impl Default for Config {
    fn default() -> Self {
        let state_dir = dirs::state_dir()
            .unwrap_or_else(|| {
                dirs::home_dir()
                    .unwrap_or_else(|| PathBuf::from("/home/agent"))
                    .join(".local/state")
            })
            .join("tui-journal");

        Self {
            backend_type: BackendType::Sqlite,
            scroll_per_page: 5,
            sync_os_clipboard: false,
            history_limit: 10,
            colored_tags: true,
            datum_visibility: DatumVisibility::Show,
            app_state_dir: state_dir,
            export: ExportConfig::default(),
            external_editor: ExternalEditorConfig::default(),
            json_backend: JsonBackendConfig::default(),
            sqlite_backend: SqliteBackendConfig::default(),
        }
    }
}

pub struct ResolvedConfig {
    pub config: Config,
    pub themes_path: PathBuf,
}

pub fn resolve_config(
    custom_config_path: Option<&str>,
    cli_json: Option<&str>,
    cli_sqlite: Option<&str>,
    cli_backend: Option<&str>,
) -> Result<ResolvedConfig, String> {
    let default_config_dir = dirs::config_dir()
        .unwrap_or_else(|| {
            dirs::home_dir()
                .unwrap_or_else(|| PathBuf::from("/home/agent"))
                .join(".config")
        })
        .join("tui-journal");

    let mut config = Config::default();
    let mut themes_path = default_config_dir.join("themes.toml");

    if let Some(path_str) = custom_config_path {
        let p = Path::new(path_str);
        if !p.exists() {
            return Err(format!("Error: Provided custom directory doesn't exit. Path: {}", path_str));
        }
        if p.is_file() {
            println!("INFO: Custom config directory is ignored in themese because it's not a directory.");
            if let Ok(content) = std::fs::read_to_string(p) {
                match toml::from_str::<Config>(&content) {
                    Ok(parsed) => config = parsed,
                    Err(e) => return Err(format!("Error: Failed to read configuration file. Error infos: {}", e)),
                }
            }
        } else if p.is_dir() {
            themes_path = p.join("themes.toml");
            let cfg_file = p.join("config.toml");
            if cfg_file.exists() {
                if let Ok(content) = std::fs::read_to_string(&cfg_file) {
                    match toml::from_str::<Config>(&content) {
                        Ok(parsed) => config = parsed,
                        Err(e) => return Err(format!("Error: Failed to read configuration file. Error infos: {}", e)),
                    }
                }
            }
        }
    } else {
        let cfg_file = default_config_dir.join("config.toml");
        if cfg_file.exists() {
            if let Ok(content) = std::fs::read_to_string(&cfg_file) {
                match toml::from_str::<Config>(&content) {
                    Ok(parsed) => config = parsed,
                    Err(e) => return Err(format!("Error: Failed to read configuration file. Error infos: {}", e)),
                }
            }
        }
    }

    if let Some(j) = cli_json {
        config.json_backend.file_path = PathBuf::from(j);
    }
    if let Some(s) = cli_sqlite {
        config.sqlite_backend.file_path = PathBuf::from(s);
    }
    if let Some(b) = cli_backend {
        match b.to_lowercase().as_str() {
            "json" => config.backend_type = BackendType::Json,
            "sqlite" => config.backend_type = BackendType::Sqlite,
            _ => {}
        }
    }

    Ok(ResolvedConfig {
        config,
        themes_path,
    })
}
EOF"}

