#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct StyleDef {
    pub fg: Option<String>,
    pub bg: Option<String>,
    pub modifiers: Option<String>,
    pub underline_color: Option<String>,
}

impl StyleDef {
    pub fn to_style(&self) -> Style {
        let mut style = Style::default();
        if let Some(ref fg) = self.fg {
            if let Some(c) = parse_color(fg) {
                style = style.fg(c);
            }
        }
        if let Some(ref bg) = self.bg {
            if let Some(c) = parse_color(bg) {
                style = style.bg(c);
            }
        }
        if let Some(ref m) = self.modifiers {
            style = style.add_modifier(parse_modifiers(m));
        }
        if let Some(ref uc) = self.underline_color {
            if let Some(c) = parse_color(uc) {
                style = style.underline_color(c);
            }
        }
        style
    }
}

fn parse_color(s: &str) -> Option<Color> {
    if s.starts_with('#') && s.len() == 7 {
        if let (Ok(r), Ok(g), Ok(b)) = (
            u8::from_str_radix(&s[1..3], 16),
            u8::from_str_radix(&s[3..5], 16),
            u8::from_str_radix(&s[5..7], 16),
        ) {
            return Some(Color::Rgb(r, g, b));
        }
    }
    match s.to_lowercase().as_str() {
        "reset" => Some(Color::Reset),
        "black" => Some(Color::Black),
        "red" => Some(Color::Red),
        "green" => Some(Color::Green),
        "yellow" => Some(Color::Yellow),
        "blue" => Some(Color::Blue),
        "magenta" => Some(Color::Magenta),
        "cyan" => Some(Color::Cyan),
        "gray" | "grey" => Some(Color::Gray),
        "darkgray" | "darkgrey" => Some(Color::DarkGray),
        "lightred" => Some(Color::LightRed),
        "lightgreen" => Some(Color::LightGreen),
        "lightyellow" => Some(Color::LightYellow),
        "lightblue" => Some(Color::LightBlue),
        "lightmagenta" => Some(Color::LightMagenta),
        "lightcyan" => Some(Color::LightCyan),
        "white" => Some(Color::White),
        _ => None,
    }
}

fn parse_modifiers(s: &str) -> Modifier {
    let mut modifier = Modifier::empty();
    for part in s.split('|') {
        match part.trim() {
            "BOLD" => modifier |= Modifier::BOLD,
            "DIM" => modifier |= Modifier::DIM,
            "ITALIC" => modifier |= Modifier::ITALIC,
            "UNDERLINED" => modifier |= Modifier::UNDERLINED,
            "SLOW_BLINK" => modifier |= Modifier::SLOW_BLINK,
            "RAPID_BLINK" => modifier |= Modifier::RAPID_BLINK,
            "REVERSED" => modifier |= Modifier::REVERSED,
            "HIDDEN" => modifier |= Modifier::HIDDEN,
            "CROSSED_OUT" => modifier |= Modifier::CROSSED_OUT,
            _ => {}
        }
    }
    modifier
}

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct GeneralTheme {
    pub input_block_active: Option<StyleDef>,
    pub input_block_invalid: Option<StyleDef>,
