    pub warning: Option<String>,
    pub info: Option<String>,
    pub question: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct ThemeConfig {
    pub general: Option<GeneralTheme>,
    pub journals_list: Option<JournalsListTheme>,
    pub editor: Option<EditorTheme>,
    pub msgbox: Option<MsgBoxTheme>,
}

pub struct Theme {
    pub config: ThemeConfig,
}

impl Theme {
    pub fn load_from_file(path: &Path) -> Self {
        let mut config = ThemeConfig::default();
        if path.exists() {
            if let Ok(content) = std::fs::read_to_string(path) {
                if let Ok(parsed) = toml::from_str::<ThemeConfig>(&content) {
                    config = parsed;
                }
            }
        }
        Self { config }
    }

    pub fn get_style(&self, section: &str, field: &str) -> Style {
        let default_theme: ThemeConfig = toml::from_str(DEFAULT_THEMES_TOML).unwrap();
        let style_def = match section {
            "general" => {
                let user_g = self.config.general.as_ref();
                let def_g = default_theme.general.as_ref().unwrap();
                match field {
                    "input_block_active" => user_g.and_then(|g| g.input_block_active.as_ref()).or(def_g.input_block_active.as_ref()),
                    "input_block_invalid" => user_g.and_then(|g| g.input_block_invalid.as_ref()).or(def_g.input_block_invalid.as_ref()),
                    "input_corsur_active" => user_g.and_then(|g| g.input_corsur_active.as_ref()).or(def_g.input_corsur_active.as_ref()),
                    "input_corsur_invalid" => user_g.and_then(|g| g.input_corsur_invalid.as_ref()).or(def_g.input_corsur_invalid.as_ref()),
                    "list_item_selected" => user_g.and_then(|g| g.list_item_selected.as_ref()).or(def_g.list_item_selected.as_ref()),
                    "list_highlight_active" => user_g.and_then(|g| g.list_highlight_active.as_ref()).or(def_g.list_highlight_active.as_ref()),
                    "list_highlight_inactive" => user_g.and_then(|g| g.list_highlight_inactive.as_ref()).or(def_g.list_highlight_inactive.as_ref()),
                    _ => None,
                }
            }
            "journals_list" => {
                let user_j = self.config.journals_list.as_ref();
                let def_j = default_theme.journals_list.as_ref().unwrap();
                match field {
                    "block_active" => user_j.and_then(|j| j.block_active.as_ref()).or(def_j.block_active.as_ref()),
                    "block_inactive" => user_j.and_then(|j| j.block_inactive.as_ref()).or(def_j.block_inactive.as_ref()),
                    "block_multi_select" => user_j.and_then(|j| j.block_multi_select.as_ref()).or(def_j.block_multi_select.as_ref()),
                    "highlight_active" => user_j.and_then(|j| j.highlight_active.as_ref()).or(def_j.highlight_active.as_ref()),
                    "highlight_inactive" => user_j.and_then(|j| j.highlight_inactive.as_ref()).or(def_j.highlight_inactive.as_ref()),
                    "title_active" => user_j.and_then(|j| j.title_active.as_ref()).or(def_j.title_active.as_ref()),
                    "title_inactive" => user_j.and_then(|j| j.title_inactive.as_ref()).or(def_j.title_inactive.as_ref()),
                    "title_selected" => user_j.and_then(|j| j.title_selected.as_ref()).or(def_j.title_selected.as_ref()),
                    "date_priority" => user_j.and_then(|j| j.date_priority.as_ref()).or(def_j.date_priority.as_ref()),
                    "tags_default" => user_j.and_then(|j| j.tags_default.as_ref()).or(def_j.tags_default.as_ref()),
                    _ => None,
                }
            }
            "editor" => {
                let user_e = self.config.editor.as_ref();
                let def_e = default_theme.editor.as_ref().unwrap();
                match field {
                    "block_insert" => user_e.and_then(|e| e.block_insert.as_ref()).or(def_e.block_insert.as_ref()),
                    "block_visual" => user_e.and_then(|e| e.block_visual.as_ref()).or(def_e.block_visual.as_ref()),
                    "block_normal_active" => user_e.and_then(|e| e.block_normal_active.as_ref()).or(def_e.block_normal_active.as_ref()),
                    "block_normal_inactive" => user_e.and_then(|e| e.block_normal_inactive.as_ref()).or(def_e.block_normal_inactive.as_ref()),
                    "cursor_normal" => user_e.and_then(|e| e.cursor_normal.as_ref()).or(def_e.cursor_normal.as_ref()),
                    "cursor_insert" => user_e.and_then(|e| e.cursor_insert.as_ref()).or(def_e.cursor_insert.as_ref()),
                    "cursor_visual" => user_e.and_then(|e| e.cursor_visual.as_ref()).or(def_e.cursor_visual.as_ref()),
                    "selection_style" => user_e.and_then(|e| e.selection_style.as_ref()).or(def_e.selection_style.as_ref()),
                    _ => None,
                }
            }
            _ => None,
        };

        style_def.map(|s| s.to_style()).unwrap_or_default()
    }

    pub fn get_msgbox_color(&self, kind: &str) -> Color {
        let default_theme: ThemeConfig = toml::from_str(DEFAULT_THEMES_TOML).unwrap();
        let user_m = self.config.msgbox.as_ref();
        let def_m = default_theme.msgbox.as_ref().unwrap();
        let col_str = match kind {
            "error" => user_m.and_then(|m| m.error.as_ref()).or(def_m.error.as_ref()),
            "warning" => user_m.and_then(|m| m.warning.as_ref()).or(def_m.warning.as_ref()),
            "info" => user_m.and_then(|m| m.info.as_ref()).or(def_m.info.as_ref()),
            "question" => user_m.and_then(|m| m.question.as_ref()).or(def_m.question.as_ref()),
            _ => None,
        };

        col_str.and_then(|s| parse_color(s)).unwrap_or(Color::Reset)
    }
}
