                .map_err(|e| format!("Failed to read JSON file: {}", e))?;
            if !content.trim().is_empty() {
                self.entries = serde_json::from_str(&content)
                    .map_err(|e| format!("Failed to parse JSON entries: {}", e))?;
            } else {
                self.entries = Vec::new();
            }
        } else {
            self.entries = Vec::new();
        }
        Ok(())
    }

    fn save(&self) -> Result<(), String> {
        if let Some(parent) = self.file_path.parent() {
            let _ = fs::create_dir_all(parent);
        }
        let json_str = serde_json::to_string(&self.entries)
            .map_err(|e| format!("Failed to serialize entries: {}", e))?;
        fs::write(&self.file_path, json_str)
            .map_err(|e| format!("Failed to write JSON file: {}", e))?;
        Ok(())
    }

    fn next_id(&self) -> u32 {
        self.entries.iter().map(|e| e.id).max().map(|m| m + 1).unwrap_or(0)
    }
}

impl Backend for JsonBackend {
    fn get_entries(&self) -> Result<Vec<Entry>, String> {
        Ok(self.entries.clone())
    }

    fn add_entry(
        &mut self,
        title: String,
        date: DateTime<Utc>,
        priority: Option<u32>,
        tags: Vec<String>,
    ) -> Result<Entry, String> {
        let entry = Entry {
            id: self.next_id(),
            date,
            title,
            content: String::new(),
            tags,
            priority,
        };
        self.entries.push(entry.clone());
        self.save()?;
        Ok(entry)
    }

    fn update_entry(
        &mut self,
        id: u32,
        title: String,
        date: DateTime<Utc>,
        priority: Option<u32>,
        tags: Vec<String>,
        content: String,
    ) -> Result<Entry, String> {
        if let Some(entry) = self.entries.iter_mut().find(|e| e.id == id) {
            entry.title = title;
            entry.date = date;
            entry.priority = priority;
            entry.tags = tags;
            entry.content = content;
