        self.entries.retain(|e| !ids.contains(&e.id));
        self.save()
    }

    fn assign_priority(&mut self, priority: u32) -> Result<(), String> {
        for entry in self.entries.iter_mut() {
            if entry.priority.is_none() {
                entry.priority = Some(priority);
            }
        }
