    }

    fn insert_tags(&self, entry_id: u32, tags: &[String]) -> Result<(), String> {
        let delete_sql = CString::new("DELETE FROM tags WHERE entry_id = ?;").unwrap();
        unsafe {
            let mut stmt: *mut c_void = std::ptr::null_mut();
            if sqlite3_prepare_v2(self.db, delete_sql.as_ptr(), -1, &mut stmt, std::ptr::null_mut()) == SQLITE_OK {
                sqlite3_bind_int(stmt, 1, entry_id as c_int);
                sqlite3_step(stmt);
                sqlite3_finalize(stmt);
            }
        }

        let insert_sql = CString::new("INSERT OR IGNORE INTO tags (entry_id, tag) VALUES (?, ?);").unwrap();
        for tag in tags {
            if tag.trim().is_empty() { continue; }
            unsafe {
                let mut stmt: *mut c_void = std::ptr::null_mut();
                if sqlite3_prepare_v2(self.db, insert_sql.as_ptr(), -1, &mut stmt, std::ptr::null_mut()) == SQLITE_OK {
