                .long("sqlite-file-path")
                .value_name("FILE PATH")
                .help("Sets the entries sqlite file path and starts using it"),
        )
        .arg(
            Arg::new("backend-type")
                .short('b')
                .long("backend-type")
                .value_name("BACKEND_TYPE")
                .value_parser(["json", "sqlite"])
                .help("Sets the backend type and starts using it"),
        )
        .arg(
            Arg::new("config")
                .short('c')
                .long("config")
                .value_name("DIR PATH")
                .help("Specifies the path for the configuration directory.\nConfiguration files is considered as root for themes file too.\nIt still accepts the path for configuration file for backward compatibility.\n(default path: /home/agent/.config/tui-journal)"),
        )
        .arg(
            Arg::new("verbose")
                .short('v')
                .long("verbose")
                .action(ArgAction::Count)
                .help("Increases logging verbosity each use for up to 3 times"),
        )
        .arg(
            Arg::new("log")
                .short('l')
                .long("log")
                .value_name("FILE PATH")
                .help("Specifies a file to use for logging\n(default file: /home/agent/.cache/tui-journal/tui-journal.log)"),
        )
        .subcommand(
            Command::new("print-config")
                .visible_alias("pc")
                .about("Print the current settings including the paths for the back-end files"),
        )
        .subcommand(
            Command::new("import-journals")
                .visible_alias("imj")
                .about("Import journals from the given transfer JSON file to the current back-end file")
                .arg(
                    Arg::new("path")
                        .short('p')
                        .long("path")
                        .value_name("FILE PATH")
                        .required(true)
                        .help("Path of the JSON file to import from"),
                ),
        )
        .subcommand(
            Command::new("assign-priority")
                .visible_alias("ap")
                .about("Assign priority for all the entries with empty priority field")
                .arg(
                    Arg::new("PRIORITY")
                        .required(true)
                        .value_parser(clap::value_parser!(u32))
                        .help("Priority value (Positive number)"),
                ),
        )
        .subcommand(
            Command::new("theme")
                .visible_alias("style")
                .about("Provides commands regarding changing themes and styles of the app")
                .subcommand(
                    Command::new("print-path")
                        .visible_alias("path")
                        .about("Prints the path to the user themes file"),
                )
                .subcommand(
                    Command::new("print-default")
                        .visible_alias("default")
                        .about("Dumps the styles with the default values to be used as a reference and base for user custom themes"),
                )
                .subcommand(
                    Command::new("write-defaults")
                        .visible_alias("write")
                        .about("Creates user custom themes file if doesn't exist then writes the default styles to it"),
                ),
        );

    let matches = cmd.get_matches();

    let json_file_path = matches.get_one::<String>("json-file-path").cloned();
    let sqlite_file_path = matches.get_one::<String>("sqlite-file-path").cloned();
    let backend_type = matches.get_one::<String>("backend-type").cloned();
    let config_dir = matches.get_one::<String>("config").cloned();
    let verbose = matches.get_count("verbose");
    let log_file = matches.get_one::<String>("log").cloned();

    let subcommand = match matches.subcommand() {
        Some(("print-config", _)) => Some(Subcommand::PrintConfig),
        Some(("import-journals", sub_m)) => {
            let path = sub_m.get_one::<String>("path").unwrap().clone();
            Some(Subcommand::ImportJournals { path })
        }
        Some(("assign-priority", sub_m)) => {
            let priority = *sub_m.get_one::<u32>("PRIORITY").unwrap();
            Some(Subcommand::AssignPriority { priority })
        }
        Some(("theme", sub_m)) => match sub_m.subcommand() {
            Some(("print-path", _)) => Some(Subcommand::Theme(ThemeSubcommand::PrintPath)),
            Some(("print-default", _)) => Some(Subcommand::Theme(ThemeSubcommand::PrintDefault)),
            Some(("write-defaults", _)) => Some(Subcommand::Theme(ThemeSubcommand::WriteDefaults)),
            _ => None,
        },
        _ => None,
    };

    CliArgs {
        json_file_path,
        sqlite_file_path,
        backend_type,
        config_dir,
        verbose,
        log_file,
        subcommand,
    }
}
EOF"}

