pub struct TextEditor {
    pub lines: Vec<String>,
    pub cursor_row: usize,
    pub cursor_col: usize,
    pub mode: EditorMode,
    pub is_dirty: bool,
    pub selection_anchor: Option<(usize, usize)>,
    pub clipboard: String,
}

impl Default for TextEditor {
    fn default() -> Self {
        Self {
            lines: vec![String::new()],
            cursor_row: 0,
            cursor_col: 0,
            mode: EditorMode::Normal,
            is_dirty: false,
            selection_anchor: None,
            clipboard: String::new(),
        }
    }
}

impl TextEditor {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn get_content(&self) -> String {
        self.lines.join("\n")
    }

    pub fn set_content(&mut self, content: &str) {
        let lines: Vec<String> = content.split('\n').map(|s| s.to_string()).collect();
        self.lines = if lines.is_empty() {
            vec![String::new()]
        } else {
            lines
        };
        self.cursor_row = 0;
        self.cursor_col = 0;
        self.mode = EditorMode::Normal;
        self.is_dirty = false;
        self.selection_anchor = None;
    }

    pub fn line_len(&self) -> usize {
        self.lines.get(self.cursor_row).map(|l| l.chars().count()).unwrap_or(0)
    }

    pub fn fix_col(&mut self) {
        let len = self.line_len();
        if self.cursor_col > len {
            self.cursor_col = len;
        }
    }

    pub fn insert_char(&mut self, c: char) {
        if self.cursor_row < self.lines.len() {
            let line = &mut self.lines[self.cursor_row];
            let idx = line.chars().take(self.cursor_col).map(|ch| ch.len_utf8()).sum();
            line.insert(idx, c);
            self.cursor_col += 1;
            self.is_dirty = true;
        }
    }

    pub fn insert_newline(&mut self) {
        if self.cursor_row < self.lines.len() {
            let line = &mut self.lines[self.cursor_row];
            let idx = line.chars().take(self.cursor_col).map(|ch| ch.len_utf8()).sum();
            let remainder = line[idx..].to_string();
            line.truncate(idx);
            self.lines.insert(self.cursor_row + 1, remainder);
            self.cursor_row += 1;
            self.cursor_col = 0;
            self.is_dirty = true;
        }
    }

    pub fn backspace(&mut self) {
        if self.cursor_col > 0 {
            if self.cursor_row < self.lines.len() {
                let line = &mut self.lines[self.cursor_row];
                let idx = line.chars().take(self.cursor_col - 1).map(|ch| ch.len_utf8()).sum();
                let char_len = line[idx..].chars().next().map(|ch| ch.len_utf8()).unwrap_or(1);
                line.replace_range(idx..idx + char_len, "");
                self.cursor_col -= 1;
                self.is_dirty = true;
            }
        } else if self.cursor_row > 0 {
            let current_line = self.lines.remove(self.cursor_row);
            self.cursor_row -= 1;
            let prev_len = self.lines[self.cursor_row].chars().count();
            self.lines[self.cursor_row].push_str(&current_line);
            self.cursor_col = prev_len;
            self.is_dirty = true;
        }
    }

    pub fn delete_char(&mut self) {
        let len = self.line_len();
        if self.cursor_col < len {
            let line = &mut self.lines[self.cursor_row];
            let idx = line.chars().take(self.cursor_col).map(|ch| ch.len_utf8()).sum();
            let char_len = line[idx..].chars().next().map(|ch| ch.len_utf8()).unwrap_or(1);
            line.replace_range(idx..idx + char_len, "");
            self.is_dirty = true;
        } else if self.cursor_row + 1 < self.lines.len() {
            let next_line = self.lines.remove(self.cursor_row + 1);
            self.lines[self.cursor_row].push_str(&next_line);
            self.is_dirty = true;
        }
    }

    pub fn delete_to_end_of_line(&mut self) {
        if self.cursor_row < self.lines.len() {
            let line = &mut self.lines[self.cursor_row];
            let idx = line.chars().take(self.cursor_col).map(|ch| ch.len_utf8()).sum();
            line.truncate(idx);
            self.is_dirty = true;
        }
    }
}
EOF"}

