            KeyCode::Char('e') if key.modifiers.contains(KeyModifiers::ALT) || key.modifiers.contains(KeyModifiers::CONTROL) => {
                self.open_external_editor()?;
            }
            KeyCode::Char('e') => {
                if let Some(entry) = self.get_selected_entry() {
                    let date_str = entry.date.with_timezone(&Local).format("%d-%m-%Y").to_string();
                    let prio_str = entry.priority.map(|p| p.to_string()).unwrap_or_default();
                    let tags_str = entry.tags.join(", ");
                    self.active_popup = Some(Popup::EditEntry {
                        id: entry.id,
                        title: entry.title.clone(),
                        date_str,
                        priority: prio_str,
                        tags_str,
                        focus: 0,
                    });
                }
            }
            KeyCode::Char('d') | KeyCode::Delete => {
                if self.get_selected_entry().is_some() {
                    self.active_popup = Some(Popup::DeleteEntry {
                        is_multi: false,
                        count: 1,
                        focus_yes: true,
                    });
                }
            }
            KeyCode::Char('v') => {
                self.is_multi_select = true;
            }
            KeyCode::Char('f') => {
                let mut all_tags = HashSet::new();
                for e in &self.entries {
                    for t in &e.tags {
                        all_tags.insert(t.clone());
                    }
                }
                let mut sorted_tags: Vec<String> = all_tags.into_iter().collect();
                sorted_tags.sort();

                let (m_all, t, c, p, sel_t) = if let Some(ref filter) = self.filter_criteria {
                    (
                        filter.matching_all,
                        filter.title.clone(),
                        filter.content.clone(),
                        filter.priority.clone(),
                        filter.tags.clone(),
                    )
                } else {
                    (true, String::new(), String::new(), String::new(), Vec::new())
                };

                self.active_popup = Some(Popup::Filter {
                    matching_all: m_all,
                    title: t,
                    content: c,
                    priority: p,
                    all_tags: sorted_tags,
                    selected_tags: sel_t,
                    focus: 0,
                    tag_list_index: 0,
                });
            }
            KeyCode::Char('o') => {
                let all_crits = vec!["Date".to_string(), "Priority".to_string(), "Title".to_string()];
                let avail: Vec<String> = all_crits
                    .into_iter()
                    .filter(|c| !self.sort_criteria.applied.contains(c))
                    .collect();

                self.active_popup = Some(Popup::Sort {
                    descending: self.sort_criteria.descending,
                    available: avail,
                    applied: self.sort_criteria.applied.clone(),
                    focus: 0,
                    avail_index: 0,
                    applied_index: 0,
                });
            }
            KeyCode::Char('?') => {
                self.active_popup = Some(Popup::Help { tab: 0, scroll: 0 });
            }
            KeyCode::Char('>') => {
                if let Some(entry) = self.get_selected_entry() {
