fn render_journals_list(f: &mut Frame, app: &App, area: Rect) {
    let is_focused = app.focused_pane == Pane::Journals;
    let title = if app.is_multi_select {
        "Journals - Multi-Select"
    } else {
        "Journals"
    };

    let block_style = if app.is_multi_select {
        app.theme.get_style("journals_list", "block_multi_select")
    } else if is_focused {
        app.theme.get_style("journals_list", "block_active")
    } else {
        app.theme.get_style("journals_list", "block_inactive")
    };

    let count_str = if app.filtered_indices.is_empty() {
        "0/0".to_string()
    } else {
        format!("{}/{}", app.selected_index + 1, app.filtered_indices.len())
    };

    let block = Block::default()
        .title(title)
        .title_alignment(Alignment::Left)
        .title(Line::from(Span::raw(count_str)).alignment(Alignment::Right))
        .borders(Borders::ALL)
        .border_style(block_style);

    if app.filtered_indices.is_empty() {
        let text = vec![
            Line::from(""),
            Line::from(""),
            Line::from("Use 'n' to create new"),
            Line::from("entry"),
        ];
        let p = Paragraph::new(text)
            .alignment(Alignment::Center)
            .block(block);
        f.render_widget(p, area);
        return;
    }

    let mut items = Vec::new();
    for (list_idx, &entry_idx) in app.filtered_indices.iter().enumerate() {
        let entry = &app.entries[entry_idx];
        let is_selected = list_idx == app.selected_index;
        let is_multi_marked = app.multi_selected.contains(&entry.id);

        let prefix = if is_selected {
            if is_multi_marked { "> * " } else { "> " }
        } else {
            if is_multi_marked { "  * " } else { "  " }
        };

        let title_style = if is_selected {
            app.theme.get_style("journals_list", "title_selected")
        } else if is_focused {
            app.theme.get_style("journals_list", "title_active")
        } else {
            app.theme.get_style("journals_list", "title_inactive")
        };

        let mut lines = vec![Line::from(vec![
            Span::styled(prefix, title_style),
            Span::styled(&entry.title, title_style),
        ])];

        let local_date = entry.date.with_timezone(&Local);
        let date_str = format!("{},{},{}", local_date.day(), local_date.month(), local_date.year());
        let prio_str = if let Some(p) = entry.priority {
            format!("  {} | Priority: {}", date_str, p)
        } else {
            format!("  {}", date_str)
        };

        let date_style = app.theme.get_style("journals_list", "date_priority");
        lines.push(Line::from(Span::styled(prio_str, date_style)));

        if !entry.tags.is_empty() {
            let tags_str = format!("  {}", entry.tags.join(" | "));
            let tags_style = app.theme.get_style("journals_list", "tags_default");
            lines.push(Line::from(Span::styled(tags_str, tags_style)));
        }

        let bg_style = if is_selected {
            if is_focused {
                app.theme.get_style("journals_list", "highlight_active")
            } else {
                app.theme.get_style("journals_list", "highlight_inactive")
            }
        } else {
            Style::default()
        };

        items.push(ListItem::new(lines).style(bg_style));
    }

    let list = List::new(items).block(block);
    f.render_widget(list, area);
}

fn render_content_editor(f: &mut Frame, app: &App, area: Rect) {
    let is_focused = app.focused_pane == Pane::Content;
    let title = if is_focused {
        let mode_str = match app.editor.mode {
            EditorMode::Normal => "NORMAL",
            EditorMode::Insert => "EDIT",
            EditorMode::Visual => "VISUAL",
        };
        let dirty_str = if app.editor.is_dirty { " *" } else { "" };
        format!("Content - {}{}", mode_str, dirty_str)
    } else {
        "Content".to_string()
    };

    let block_style = if is_focused {
        match app.editor.mode {
            EditorMode::Insert => app.theme.get_style("editor", "block_insert"),
            EditorMode::Visual => app.theme.get_style("editor", "block_visual"),
            EditorMode::Normal => app.theme.get_style("editor", "block_normal_active"),
        }
    } else {
        app.theme.get_style("editor", "block_normal_inactive")
    };

    let block = Block::default()
        .title(title)
        .borders(Borders::ALL)
        .border_style(block_style);

    let inner = block.inner(area);
    f.render_widget(block, area);

    let content_lines: Vec<Line> = app
        .editor
        .lines
        .iter()
        .map(|l| Line::from(l.as_str()))
        .collect();

    let p = Paragraph::new(content_lines).wrap(Wrap { trim: false });
    f.render_widget(p, inner);

    if is_focused {
        let cursor_x = inner.x + app.editor.cursor_col as u16;
        let cursor_y = inner.y + app.editor.cursor_row as u16;
        if cursor_x < inner.x + inner.width && cursor_y < inner.y + inner.height {
            f.set_cursor_position((cursor_x, cursor_y));
        }
    }
}

fn render_footer(f: &mut Frame, app: &App, area: Rect) {
    let text = if app.is_multi_select {
        "Leave journals multi selection mode: 'q','v','Esc','<Ctrl-c>' | Show help: '?'"
    } else if app.focused_pane == Pane::Content && app.editor.mode == EditorMode::Insert {
        "Back to Editor Normal Mode: 'Esc','<Ctrl-c>','<Ctrl-[>' |  Edit using Emacs motions"
    } else if app.focused_pane == Pane::Content {
        "Exit: 'q' | Edit journal content: 'Enter','<Ctrl-m>' | Show help: '?'"
    } else {
        "Exit: 'q' | Edit journal content: 'Enter','<Ctrl-m>' | Open filter: 'f' | Open sort options: 'o' | Show help: '?'"
    };

    let p = Paragraph::new(text).wrap(Wrap { trim: true });
    f.render_widget(p, area);
}

