            let inner = block.inner(popup_area);
            f.render_widget(block, popup_area);

            let chunks = Layout::default()
                .direction(Direction::Vertical)
                .constraints([
                    Constraint::Length(2),
                    Constraint::Length(3),
                    Constraint::Min(2),
                ])
                .split(inner);

            let p_info = Paragraph::new(format!("Export the selected {} journals", count));
            f.render_widget(p_info, chunks[0]);

            let active_style = app.theme.get_style("general", "input_block_active");
            let p_path = Paragraph::new(path_str.as_str()).block(
                Block::default().title("Path").borders(Borders::ALL).border_style(active_style),
            );
            f.render_widget(p_path, chunks[1]);

            let p_footer = Paragraph::new("Enter: confirm | Esc or <Ctrl-c>: Cancel").alignment(Alignment::Center);
            f.render_widget(p_footer, chunks[2]);
        }
        Popup::Import { path_str } => {
            let popup_area = centered_rect(65, 35, area);
