                Block::default().title("Path").borders(Borders::ALL).border_style(active_style),
            );
            f.render_widget(p_path, chunks[0]);

            let p_footer = Paragraph::new("Enter: confirm | Esc or <Ctrl-c>: Cancel").alignment(Alignment::Center);
            f.render_widget(p_footer, chunks[1]);
        }
        Popup::MsgBox {
            title,
            message,
            kind: _,
            is_confirm: _,
            focus_yes: _,
        } => {
            let popup_area = centered_rect(50, 30, area);
            f.render_widget(Clear, popup_area);

            let block = Block::default().title(title.as_str()).borders(Borders::ALL);
            let inner = block.inner(popup_area);
            f.render_widget(block, popup_area);

            let text = vec![
                Line::from(""),
                Line::from(message.as_str()).alignment(Alignment::Center),
                Line::from(""),
                Line::from("(O)k").alignment(Alignment::Center),
            ];

            let p = Paragraph::new(text);
            f.render_widget(p, inner);
        }
    }
}

fn centered_rect(percent_x: u16, percent_y: u16, r: Rect) -> Rect {
    let popup_layout = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Percentage((100 - percent_y) / 2),
            Constraint::Percentage(percent_y),
            Constraint::Percentage((100 - percent_y) / 2),
        ])
        .split(r);

    Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage((100 - percent_x) / 2),
            Constraint::Percentage(percent_x),
            Constraint::Percentage((100 - percent_x) / 2),
        ])
        .split(popup_layout[1])[1]
}
