use app::{popups::MsgBoxKind, popups::Popup, ui::ui, App};
use backend::{json::JsonBackend, sqlite::SqliteBackend, Backend};
use cli::{Subcommand, ThemeSubcommand};
use config::BackendType;
use crossterm::{
    event::{self, Event},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::{backend::CrosstermBackend, Terminal};
use std::io;
use std::time::Duration;

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args = cli::parse_cli();

    let resolved = match config::resolve_config(
        args.config_dir.as_deref(),
        args.json_file_path.as_deref(),
        args.sqlite_file_path.as_deref(),
        args.backend_type.as_deref(),
    ) {
        Ok(res) => res,
        Err(err) => {
            eprintln!("{}", err);
            std::process::exit(1);
        }
    };

    let cfg = resolved.config;
    let themes_path = resolved.themes_path;

    if let Some(ref sub) = args.subcommand {
        match sub {
            Subcommand::PrintConfig => {
                let toml_str = toml::to_string_pretty(&cfg).unwrap();
                print!("{}", toml_str);
                return Ok(());
            }
            Subcommand::Theme(ThemeSubcommand::PrintPath) => {
                println!("{}", themes_path.display());
                return Ok(());
            }
            Subcommand::Theme(ThemeSubcommand::PrintDefault) => {
                print!("{}", theme::DEFAULT_THEMES_TOML);
                return Ok(());
            }
            Subcommand::Theme(ThemeSubcommand::WriteDefaults) => {
                if themes_path.exists() {
                    eprintln!("Error: Themes file already exists. Path: {}", themes_path.display());
                    std::process::exit(1);
                } else {
                    if let Some(parent) = themes_path.parent() {
                        let _ = std::fs::create_dir_all(parent);
                    }
                    std::fs::write(&themes_path, theme::DEFAULT_THEMES_TOML)?;
                    println!("Default themes have been written to {}", themes_path.display());
                    return Ok(());
                }
            }
            _ => {}
        }
    }

    let default_log_dir = dirs::cache_dir()
        .unwrap_or_else(|| {
            dirs::home_dir()
                .unwrap_or_else(|| std::path::PathBuf::from("/home/agent"))
                .join(".cache")
        })
        .join("tui-journal");
    let default_log_path = default_log_dir.join("tui-journal.log");
    let log_path = args
        .log_file
        .as_ref()
        .map(std::path::PathBuf::from)
        .unwrap_or(default_log_path);

    logging::init_logging(&log_path, args.verbose);

    let theme = theme::Theme::load_from_file(&themes_path);

    let mut backend: Box<dyn Backend> = match cfg.backend_type {
        BackendType::Json => Box::new(JsonBackend::new(cfg.json_backend.file_path.clone())?),
        BackendType::Sqlite => Box::new(SqliteBackend::new(cfg.sqlite_backend.file_path.clone())?),
    };

    let mut initial_popup: Option<Popup> = None;

    if let Some(ref sub) = args.subcommand {
        match sub {
            Subcommand::AssignPriority { priority } => {
                backend.assign_priority(*priority)?;
            }
            Subcommand::ImportJournals { path } => {
                let p = std::path::Path::new(path);
                if !p.exists() {
                    initial_popup = Some(Popup::MsgBox {
                        title: "Error".to_string(),
                        message: format!("Import file doesn't exist: path {}", path),
                        kind: MsgBoxKind::Error,
                        is_confirm: false,
                        focus_yes: true,
                    });
                } else {
                    match std::fs::read_to_string(p) {
                        Ok(content) => match serde_json::from_str::<model::TransferData>(&content) {
                            Ok(transfer) => {
                                backend.import_entries(&transfer.entries)?;
                            }
                            Err(e) => {
                                initial_popup = Some(Popup::MsgBox {
                                    title: "Error".to_string(),
                                    message: format!("Failed to parse transfer file: {}", e),
                                    kind: MsgBoxKind::Error,
                                    is_confirm: false,
                                    focus_yes: true,
                                });
                            }
                        },
                        Err(e) => {
                            initial_popup = Some(Popup::MsgBox {
                                title: "Error".to_string(),
                                message: format!("Failed to read transfer file: {}", e),
                                kind: MsgBoxKind::Error,
                                is_confirm: false,
                                focus_yes: true,
                            });
                        }
                    }
                }
            }
            _ => {}
        }
    }

    let mut app = App::new(cfg, theme, backend)?;
    if initial_popup.is_some() {
        app.active_popup = initial_popup;
    }

    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let crossterm_backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(crossterm_backend)?;

    loop {
        terminal.draw(|f| ui(f, &app))?;

        if event::poll(Duration::from_millis(50))? {
            if let Event::Key(key) = event::read()? {
                app.handle_key_event(key)?;
            }
        }

        if app.should_quit {
            break;
        }
    }

    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    Ok(())
}
