        if let Some(entry) = self.get_selected_entry().cloned() {
            let new_content = self.editor.get_content();
            let updated = self.backend.update_entry(
                entry.id,
                entry.title,
                entry.date,
                entry.priority,
                entry.tags,
                new_content,
            )?;
            if let Some(e) = self.entries.iter_mut().find(|e| e.id == updated.id) {
                e.content = updated.content;
            }
            self.editor.is_dirty = false;
        }
        Ok(())
    }

    pub fn handle_key_event(&mut self, key: KeyEvent) -> Result<(), String> {
        if let Some(popup) = self.active_popup.clone() {
            self.handle_popup_key(key, popup)?;
            return Ok(());
        }

        if self.is_multi_select {
            self.handle_multi_select_key(key)?;
            return Ok(());
        }

        match self.focused_pane {
            Pane::Journals => self.handle_journals_pane_key(key)?,
            Pane::Content => self.handle_content_pane_key(key)?,
        }

        Ok(())
    }

    fn handle_journals_pane_key(&mut self, key: KeyEvent) -> Result<(), String> {
        match key.code {
            KeyCode::Char('q') => self.should_quit = true,
            KeyCode::Tab | KeyCode::BackTab => {
                self.focused_pane = Pane::Content;
            }
            KeyCode::Char('l') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                self.focused_pane = Pane::Content;
            }
            KeyCode::Char('j') | KeyCode::Down => {
                if !self.filtered_indices.is_empty()
                    && self.selected_index + 1 < self.filtered_indices.len()
                {
                    self.selected_index += 1;
                    self.sync_editor_content();
                }
            }
            KeyCode::Char('k') | KeyCode::Up => {
                if self.selected_index > 0 {
                    self.selected_index -= 1;
                    self.sync_editor_content();
                }
            }
            KeyCode::PageDown => {
                if !self.filtered_indices.is_empty() {
                    self.selected_index = (self.selected_index + self.config.scroll_per_page)
                        .min(self.filtered_indices.len() - 1);
                    self.sync_editor_content();
                }
            }
            KeyCode::PageUp => {
                self.selected_index = self
                    .selected_index
                    .saturating_sub(self.config.scroll_per_page);
                self.sync_editor_content();
            }
            KeyCode::Char('d') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                if !self.filtered_indices.is_empty() {
                    self.selected_index = (self.selected_index + self.config.scroll_per_page)
                        .min(self.filtered_indices.len() - 1);
                    self.sync_editor_content();
                }
            }
            KeyCode::Char('u') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                self.selected_index = self
                    .selected_index
                    .saturating_sub(self.config.scroll_per_page);
                self.sync_editor_content();
            }
            KeyCode::Home | KeyCode::Char('g') => {
                self.selected_index = 0;
                self.sync_editor_content();
            }
            KeyCode::End | KeyCode::Char('G') => {
                if !self.filtered_indices.is_empty() {
                    self.selected_index = self.filtered_indices.len() - 1;
                    self.sync_editor_content();
                }
            }
            KeyCode::Enter => {
                self.focused_pane = Pane::Content;
                self.editor.mode = EditorMode::Insert;
            }
            KeyCode::Char('m') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                self.focused_pane = Pane::Content;
                self.editor.mode = EditorMode::Insert;
            }
            KeyCode::Char('n') => {
                let today = Local::now().format("%d-%m-%Y").to_string();
                self.active_popup = Some(Popup::CreateEntry {
                    title: String::new(),
                    date_str: today,
                    priority: String::new(),
                    tags_str: String::new(),
                    focus: 0,
                });
            }
            KeyCode::Char('e') if key.modifiers.contains(KeyModifiers::ALT) || key.modifiers.contains(KeyModifiers::CONTROL) => {
                self.open_external_editor()?;
            }
            KeyCode::Char('e') => {
                if let Some(entry) = self.get_selected_entry() {
                    let date_str = entry.date.with_timezone(&Local).format("%d-%m-%Y").to_string();
                    let prio_str = entry.priority.map(|p| p.to_string()).unwrap_or_default();
                    let tags_str = entry.tags.join(", ");
                    self.active_popup = Some(Popup::EditEntry {
                        id: entry.id,
                        title: entry.title.clone(),
                        date_str,
                        priority: prio_str,
                        tags_str,
                        focus: 0,
                    });
                }
            }
            KeyCode::Char('d') | KeyCode::Delete => {
                if self.get_selected_entry().is_some() {
                    self.active_popup = Some(Popup::DeleteEntry {
                        is_multi: false,
                        count: 1,
                        focus_yes: true,
                    });
                }
            }
            KeyCode::Char('v') => {
                self.is_multi_select = true;
            }
            KeyCode::Char('f') => {
                let mut all_tags = HashSet::new();
                for e in &self.entries {
                    for t in &e.tags {
                        all_tags.insert(t.clone());
                    }
                }
                let mut sorted_tags: Vec<String> = all_tags.into_iter().collect();
                sorted_tags.sort();

                let (m_all, t, c, p, sel_t) = if let Some(ref filter) = self.filter_criteria {
                    (
                        filter.matching_all,
                        filter.title.clone(),
                        filter.content.clone(),
                        filter.priority.clone(),
                        filter.tags.clone(),
                    )
                } else {
                    (true, String::new(), String::new(), String::new(), Vec::new())
                };

                self.active_popup = Some(Popup::Filter {
                    matching_all: m_all,
                    title: t,
                    content: c,
                    priority: p,
                    all_tags: sorted_tags,
                    selected_tags: sel_t,
                    focus: 0,
                    tag_list_index: 0,
                });
            }
            KeyCode::Char('o') => {
                let all_crits = vec!["Date".to_string(), "Priority".to_string(), "Title".to_string()];
                let avail: Vec<String> = all_crits
                    .into_iter()
                    .filter(|c| !self.sort_criteria.applied.contains(c))
                    .collect();

                self.active_popup = Some(Popup::Sort {
                    descending: self.sort_criteria.descending,
                    available: avail,
                    applied: self.sort_criteria.applied.clone(),
                    focus: 0,
                    avail_index: 0,
                    applied_index: 0,
                });
            }
            KeyCode::Char('?') => {
                self.active_popup = Some(Popup::Help { tab: 0, scroll: 0 });
            }
            KeyCode::Char('>') => {
                if let Some(entry) = self.get_selected_entry() {
                    let default_path = format!("/workspace/{}.txt", entry.title);
                    self.active_popup = Some(Popup::ExportSingle {
                        id: entry.id,
                        title: entry.title.clone(),
                        path_str: default_path,
                    });
                }
            }
            KeyCode::Char('<') => {
                self.active_popup = Some(Popup::Import {
                    path_str: "/workspace/tjournal_export.json".to_string(),
                });
            }
            KeyCode::Char('r') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                self.reload_entries()?;
            }
            _ => {}
        }
        Ok(())
    }

    fn handle_content_pane_key(&mut self, key: KeyEvent) -> Result<(), String> {
        match self.editor.mode {
            EditorMode::Normal => match key.code {
                KeyCode::Char('q') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.sync_editor_content();
                }
                KeyCode::Char('q') => self.should_quit = true,
                KeyCode::Tab | KeyCode::BackTab => {
                    self.focused_pane = Pane::Journals;
                }
                KeyCode::Char('h') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.focused_pane = Pane::Journals;
                }
                KeyCode::Char('s') if key.modifiers.contains(KeyModifiers::CONTROL) || key.code == KeyCode::Char('s') => {
                    self.save_current_editor_content()?;
                }
                KeyCode::Char('i') => {
                    self.editor.mode = EditorMode::Insert;
                }
                KeyCode::Char('I') => {
                    self.editor.cursor_col = 0;
                    self.editor.mode = EditorMode::Insert;
                }
                KeyCode::Char('a') => {
                    let len = self.editor.line_len();
                    self.editor.cursor_col = (self.editor.cursor_col + 1).min(len);
                    self.editor.mode = EditorMode::Insert;
                }
                KeyCode::Char('A') => {
                    self.editor.cursor_col = self.editor.line_len();
                    self.editor.mode = EditorMode::Insert;
                }
                KeyCode::Char('o') => {
                    self.editor.insert_newline();
                    self.editor.mode = EditorMode::Insert;
                }
                KeyCode::Char('O') => {
                    if self.editor.cursor_row > 0 {
                        self.editor.cursor_row -= 1;
                    }
                    self.editor.insert_newline();
                    self.editor.mode = EditorMode::Insert;
                }
                KeyCode::Char('v') => {
                    self.editor.mode = EditorMode::Visual;
                    self.editor.selection_anchor = Some((self.editor.cursor_row, self.editor.cursor_col));
                }
                KeyCode::Char('h') | KeyCode::Left => {
                    self.editor.cursor_col = self.editor.cursor_col.saturating_sub(1);
                }
                KeyCode::Char('l') | KeyCode::Right => {
                    self.editor.cursor_col = (self.editor.cursor_col + 1).min(self.editor.line_len());
                }
                KeyCode::Char('k') | KeyCode::Up => {
                    self.editor.cursor_row = self.editor.cursor_row.saturating_sub(1);
                    self.editor.fix_col();
                }
                KeyCode::Char('j') | KeyCode::Down => {
                    self.editor.cursor_row = (self.editor.cursor_row + 1).min(self.editor.lines.len() - 1);
                    self.editor.fix_col();
                }
                KeyCode::Char('0') | KeyCode::Home => {
                    self.editor.cursor_col = 0;
                }
                KeyCode::Char('$') | KeyCode::End => {
                    self.editor.cursor_col = self.editor.line_len();
                }
                KeyCode::Char('g') => {
                    self.editor.cursor_row = 0;
                    self.editor.cursor_col = 0;
                }
                KeyCode::Char('G') => {
                    self.editor.cursor_row = self.editor.lines.len() - 1;
                    self.editor.cursor_col = 0;
                }
                KeyCode::Char('x') => {
                    self.editor.delete_char();
                }
                KeyCode::Char('e') if key.modifiers.contains(KeyModifiers::ALT) || key.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.open_external_editor()?;
                }
                KeyCode::Char('?') => {
                    self.active_popup = Some(Popup::Help { tab: 1, scroll: 0 });
                }
                _ => {}
            },
            EditorMode::Insert => match key.code {
                KeyCode::Esc | KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) || key.code == KeyCode::Esc => {
                    self.editor.mode = EditorMode::Normal;
                }
                KeyCode::Enter => {
                    self.editor.insert_newline();
                }
                KeyCode::Backspace => {
                    self.editor.backspace();
                }
                KeyCode::Delete => {
                    self.editor.delete_char();
                }
                KeyCode::Char('d') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.editor.delete_char();
                }
                KeyCode::Char('h') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.editor.backspace();
                }
                KeyCode::Char('k') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.editor.delete_to_end_of_line();
                }
                KeyCode::Char('a') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.editor.cursor_col = 0;
                }
                KeyCode::Char('e') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.editor.cursor_col = self.editor.line_len();
                }
                KeyCode::Char('f') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.editor.cursor_col = (self.editor.cursor_col + 1).min(self.editor.line_len());
                }
                KeyCode::Char('b') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.editor.cursor_col = self.editor.cursor_col.saturating_sub(1);
                }
                KeyCode::Char('n') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.editor.cursor_row = (self.editor.cursor_row + 1).min(self.editor.lines.len() - 1);
                    self.editor.fix_col();
                }
                KeyCode::Char('p') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.editor.cursor_row = self.editor.cursor_row.saturating_sub(1);
                    self.editor.fix_col();
                }
                KeyCode::Char(c) => {
                    self.editor.insert_char(c);
                }
                _ => {}
            },
            EditorMode::Visual => match key.code {
                KeyCode::Esc | KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) || key.code == KeyCode::Esc => {
                    self.editor.mode = EditorMode::Normal;
                }
                KeyCode::Char('h') | KeyCode::Left => {
                    self.editor.cursor_col = self.editor.cursor_col.saturating_sub(1);
                }
                KeyCode::Char('l') | KeyCode::Right => {
                    self.editor.cursor_col = (self.editor.cursor_col + 1).min(self.editor.line_len());
                }
                KeyCode::Char('k') | KeyCode::Up => {
                    self.editor.cursor_row = self.editor.cursor_row.saturating_sub(1);
                    self.editor.fix_col();
                }
                KeyCode::Char('j') | KeyCode::Down => {
                    self.editor.cursor_row = (self.editor.cursor_row + 1).min(self.editor.lines.len() - 1);
                    self.editor.fix_col();
                }
                KeyCode::Char('d') | KeyCode::Char('x') => {
                    self.editor.mode = EditorMode::Normal;
                    self.editor.is_dirty = true;
                }
                _ => {}
            },
        }
        Ok(())
    }

    fn handle_multi_select_key(&mut self, key: KeyEvent) -> Result<(), String> {
        match key.code {
            KeyCode::Char('q') | KeyCode::Char('v') | KeyCode::Esc => {
                self.is_multi_select = false;
                self.multi_selected.clear();
            }
            KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                self.is_multi_select = false;
                self.multi_selected.clear();
            }
            KeyCode::Char(' ') | KeyCode::Enter => {
                if let Some(entry) = self.get_selected_entry() {
                    let id = entry.id;
                    if self.multi_selected.contains(&id) {
                        self.multi_selected.remove(&id);
                    } else {
                        self.multi_selected.insert(id);
                    }
                }
            }
            KeyCode::Char('j') | KeyCode::Down => {
                if !self.filtered_indices.is_empty()
                    && self.selected_index + 1 < self.filtered_indices.len()
                {
                    self.selected_index += 1;
                    self.sync_editor_content();
                }
            }
            KeyCode::Char('k') | KeyCode::Up => {
                if self.selected_index > 0 {
                    self.selected_index -= 1;
                    self.sync_editor_content();
                }
            }
            KeyCode::Char('d') | KeyCode::Delete => {
                if !self.multi_selected.is_empty() {
                    self.active_popup = Some(Popup::DeleteEntry {
                        is_multi: true,
                        count: self.multi_selected.len(),
                        focus_yes: true,
                    });
                }
            }
            KeyCode::Char('>') => {
                if !self.multi_selected.is_empty() {
                    self.active_popup = Some(Popup::ExportMulti {
                        count: self.multi_selected.len(),
                        path_str: "/workspace/tjournal_export.json".to_string(),
                    });
                }
            }
            KeyCode::Char('?') => {
                self.active_popup = Some(Popup::Help { tab: 2, scroll: 0 });
            }
            _ => {}
        }
        Ok(())
    }

    fn handle_popup_key(&mut self, key: KeyEvent, mut popup: Popup) -> Result<(), String> {
        match &mut popup {
            Popup::Help { tab, scroll } => match key.code {
                KeyCode::Tab | KeyCode::Right => *tab = (*tab + 1) % 3,
                KeyCode::BackTab | KeyCode::Left => *tab = (*tab + 2) % 3,
                KeyCode::Char('j') | KeyCode::Down => *scroll += 1,
                KeyCode::Char('k') | KeyCode::Up => *scroll = scroll.saturating_sub(1),
                KeyCode::PageDown => *scroll += 5,
                KeyCode::PageUp => *scroll = scroll.saturating_sub(5),
                KeyCode::Esc | KeyCode::Char('q') => {
                    self.active_popup = None;
                    return Ok(());
                }
                _ => {}
            },
            Popup::CreateEntry {
                title,
                date_str,
                priority,
                tags_str,
                focus,
            } => match key.code {
                KeyCode::Tab => *focus = (*focus + 1) % 4,
                KeyCode::BackTab => *focus = (*focus + 3) % 4,
                KeyCode::Esc | KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) || key.code == KeyCode::Esc => {
                    self.active_popup = None;
                    return Ok(());
                }
                KeyCode::Enter => {
                    let dt = parse_date_str(date_str).unwrap_or_else(|| Utc::now());
                    let prio = priority.parse::<u32>().ok();
                    let tags = tags_str
                        .split(',')
                        .map(|s| s.trim().to_string())
                        .filter(|s| !s.is_empty())
                        .collect();

                    let added = self.backend.add_entry(title.clone(), dt, prio, tags)?;
                    self.reload_entries()?;
                    if let Some(idx) = self.filtered_indices.iter().position(|&i| self.entries[i].id == added.id) {
                        self.selected_index = idx;
                    }
                    self.active_popup = None;
                    return Ok(());
                }
                KeyCode::Backspace => {
                    let field = match *focus {
                        0 => title,
                        1 => date_str,
                        2 => priority,
                        _ => tags_str,
                    };
                    field.pop();
                }
                KeyCode::Char(c) => {
                    let field = match *focus {
                        0 => title,
                        1 => date_str,
                        2 => priority,
                        _ => tags_str,
                    };
                    field.push(c);
                }
                _ => {}
            },
            Popup::EditEntry {
                id,
                title,
                date_str,
                priority,
                tags_str,
                focus,
            } => match key.code {
                KeyCode::Tab => *focus = (*focus + 1) % 4,
                KeyCode::BackTab => *focus = (*focus + 3) % 4,
                KeyCode::Esc | KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) || key.code == KeyCode::Esc => {
                    self.active_popup = None;
                    return Ok(());
                }
                KeyCode::Enter => {
                    let dt = parse_date_str(date_str).unwrap_or_else(|| Utc::now());
                    let prio = priority.parse::<u32>().ok();
                    let tags = tags_str
                        .split(',')
                        .map(|s| s.trim().to_string())
                        .filter(|s| !s.is_empty())
                        .collect();

                    let current_content = self
                        .entries
                        .iter()
                        .find(|e| e.id == *id)
                        .map(|e| e.content.clone())
                        .unwrap_or_default();

                    self.backend.update_entry(*id, title.clone(), dt, prio, tags, current_content)?;
                    self.reload_entries()?;
                    self.active_popup = None;
                    return Ok(());
                }
                KeyCode::Backspace => {
                    let field = match *focus {
                        0 => title,
                        1 => date_str,
                        2 => priority,
                        _ => tags_str,
                    };
                    field.pop();
                }
                KeyCode::Char(c) => {
                    let field = match *focus {
                        0 => title,
                        1 => date_str,
                        2 => priority,
                        _ => tags_str,
                    };
                    field.push(c);
                }
                _ => {}
            },
            Popup::DeleteEntry {
                is_multi,
                count: _,
                focus_yes,
            } => match key.code {
                KeyCode::Left | KeyCode::Right | KeyCode::Tab => *focus_yes = !*focus_yes,
                KeyCode::Char('y') | KeyCode::Char('Y') => {
                    if *is_multi {
                        let ids: Vec<u32> = self.multi_selected.iter().cloned().collect();
                        self.backend.delete_entries(&ids)?;
                        self.multi_selected.clear();
                        self.is_multi_select = false;
                    } else if let Some(entry) = self.get_selected_entry() {
                        self.backend.delete_entry(entry.id)?;
                    }
                    self.reload_entries()?;
                    self.active_popup = None;
                    return Ok(());
                }
                KeyCode::Enter if *focus_yes => {
                    if *is_multi {
                        let ids: Vec<u32> = self.multi_selected.iter().cloned().collect();
                        self.backend.delete_entries(&ids)?;
                        self.multi_selected.clear();
                        self.is_multi_select = false;
                    } else if let Some(entry) = self.get_selected_entry() {
                        self.backend.delete_entry(entry.id)?;
                    }
                    self.reload_entries()?;
                    self.active_popup = None;
                    return Ok(());
                }
                KeyCode::Char('n') | KeyCode::Char('N') | KeyCode::Esc | KeyCode::Enter => {
                    self.active_popup = None;
                    return Ok(());
                }
                _ => {}
            },
            Popup::Filter {
                matching_all,
                title,
                content,
                priority,
                all_tags,
                selected_tags,
                focus,
                tag_list_index,
            } => match key.code {
                KeyCode::Char('r') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    *matching_all = !*matching_all;
                }
                KeyCode::Tab => *focus = (*focus + 1) % 5,
                KeyCode::BackTab => *focus = (*focus + 4) % 5,
                KeyCode::Char('j') | KeyCode::Down if *focus == 4 => {
                    if !all_tags.is_empty() {
                        *tag_list_index = (*tag_list_index + 1).min(all_tags.len() - 1);
                    }
                }
                KeyCode::Char('k') | KeyCode::Up if *focus == 4 => {
                    *tag_list_index = tag_list_index.saturating_sub(1);
                }
                KeyCode::Char(' ') if *focus == 4 => {
                    if let Some(tag) = all_tags.get(*tag_list_index) {
                        if selected_tags.contains(tag) {
                            selected_tags.retain(|t| t != tag);
                        } else {
                            selected_tags.push(tag.clone());
                        }
                    }
                }
                KeyCode::Backspace => {
                    let field = match *focus {
                        1 => Some(title),
                        2 => Some(content),
                        3 => Some(priority),
                        _ => None,
                    };
                    if let Some(f) = field {
                        f.pop();
                    }
                }
                KeyCode::Char(c) if *focus >= 1 && *focus <= 3 => {
                    let field = match *focus {
                        1 => title,
                        2 => content,
                        3 => priority,
                        _ => unreachable!(),
                    };
                    field.push(c);
                }
                KeyCode::Enter => {
                    self.filter_criteria = Some(FilterCriteria {
                        matching_all: *matching_all,
                        title: title.clone(),
                        content: content.clone(),
                        priority: priority.clone(),
                        tags: selected_tags.clone(),
                    });
                    self.apply_filter_and_sort();
                    self.active_popup = None;
                    return Ok(());
                }
                KeyCode::Esc => {
                    self.active_popup = None;
                    return Ok(());
                }
                _ => {}
            },
            Popup::Sort {
                descending,
                available,
                applied,
                focus,
                avail_index,
                applied_index,
            } => match key.code {
                KeyCode::Char('o') => *descending = !*descending,
                KeyCode::Tab => *focus = (*focus + 1) % 3,
                KeyCode::BackTab => *focus = (*focus + 2) % 3,
                KeyCode::Char('j') | KeyCode::Down => match *focus {
                    1 if !available.is_empty() => *avail_index = (*avail_index + 1).min(available.len() - 1),
                    2 if !applied.is_empty() => *applied_index = (*applied_index + 1).min(applied.len() - 1),
                    _ => {}
                },
                KeyCode::Char('k') | KeyCode::Up => match *focus {
                    1 => *avail_index = avail_index.saturating_sub(1),
                    2 => *applied_index = applied_index.saturating_sub(1),
                    _ => {}
                },
                KeyCode::Char(' ') => match *focus {
                    1 if !available.is_empty() => {
                        let item = available.remove(*avail_index);
                        applied.push(item);
                        if *avail_index >= available.len() && !available.is_empty() {
                            *avail_index = available.len() - 1;
                        }
                    }
                    2 if !applied.is_empty() => {
                        let item = applied.remove(*applied_index);
                        available.push(item);
                        if *applied_index >= applied.len() && !applied.is_empty() {
                            *applied_index = applied.len() - 1;
                        }
                    }
                    _ => {}
                },
                KeyCode::Char('d') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    *descending = true;
                    *applied = vec!["Date".to_string(), "Priority".to_string()];
                    let all_crits = vec!["Date".to_string(), "Priority".to_string(), "Title".to_string()];
                    *available = all_crits.into_iter().filter(|c| !applied.contains(c)).collect();
                    *avail_index = 0;
                    *applied_index = 0;
                }
                KeyCode::Enter => {
                    self.sort_criteria.descending = *descending;
                    self.sort_criteria.applied = applied.clone();
                    self.apply_filter_and_sort();
                    self.active_popup = None;
                    return Ok(());
                }
                KeyCode::Esc => {
                    self.active_popup = None;
                    return Ok(());
                }
                _ => {}
            },
            Popup::ExportSingle { id: _, title: _, path_str } => match key.code {
                KeyCode::Backspace => {
                    path_str.pop();
                }
                KeyCode::Char(c) => {
                    path_str.push(c);
                }
                KeyCode::Enter => {
                    let content = self.editor.get_content();
                    if let Err(e) = std::fs::write(&path_str, content) {
                        self.active_popup = Some(Popup::MsgBox {
                            title: "Error".to_string(),
                            message: format!("Failed to export file: {}", e),
                            kind: MsgBoxKind::Error,
                            is_confirm: false,
                            focus_yes: true,
                        });
                        return Ok(());
                    } else {
                        self.active_popup = None;
                        return Ok(());
                    }
                }
                KeyCode::Esc => {
                    self.active_popup = None;
                    return Ok(());
                }
                _ => {}
            },
            Popup::ExportMulti { count: _, path_str } => match key.code {
                KeyCode::Backspace => {
                    path_str.pop();
                }
                KeyCode::Char(c) => {
                    path_str.push(c);
                }
                KeyCode::Enter => {
                    let export_entries: Vec<TransferEntry> = self
                        .entries
                        .iter()
                        .filter(|e| self.multi_selected.contains(&e.id))
                        .map(|e| TransferEntry {
                            date: e.date,
                            title: e.title.clone(),
                            content: e.content.clone(),
                            tags: e.tags.clone(),
                            priority: e.priority,
                        })
                        .collect();

                    let transfer = TransferData {
                        version: 100,
                        entries: export_entries,
                    };

                    let json_str = serde_json::to_string_pretty(&transfer).unwrap();
                    if let Err(e) = std::fs::write(&path_str, json_str) {
                        self.active_popup = Some(Popup::MsgBox {
                            title: "Error".to_string(),
                            message: format!("Failed to export files: {}", e),
                            kind: MsgBoxKind::Error,
                            is_confirm: false,
                            focus_yes: true,
                        });
                        return Ok(());
                    } else {
                        self.active_popup = None;
                        return Ok(());
                    }
                }
                KeyCode::Esc => {
                    self.active_popup = None;
                    return Ok(());
                }
                _ => {}
            },
            Popup::Import { path_str } => match key.code {
                KeyCode::Backspace => {
                    path_str.pop();
                }
                KeyCode::Char(c) => {
                    path_str.push(c);
                }
                KeyCode::Enter => {
                    let p = std::path::Path::new(path_str);
                    if !p.exists() {
                        self.active_popup = Some(Popup::MsgBox {
                            title: "Error".to_string(),
                            message: format!("Import file doesn't exist: path {}", path_str),
                            kind: MsgBoxKind::Error,
                            is_confirm: false,
                            focus_yes: true,
                        });
                        return Ok(());
                    }

                    match std::fs::read_to_string(p) {
                        Ok(content) => match serde_json::from_str::<TransferData>(&content) {
                            Ok(transfer) => {
                                self.backend.import_entries(&transfer.entries)?;
                                self.reload_entries()?;
                                self.active_popup = None;
                                return Ok(());
                            }
                            Err(e) => {
                                self.active_popup = Some(Popup::MsgBox {
                                    title: "Error".to_string(),
                                    message: format!("Failed to parse transfer file: {}", e),
                                    kind: MsgBoxKind::Error,
                                    is_confirm: false,
                                    focus_yes: true,
                                });
                                return Ok(());
                            }
                        },
                        Err(e) => {
                            self.active_popup = Some(Popup::MsgBox {
                                title: "Error".to_string(),
                                message: format!("Failed to read transfer file: {}", e),
                                kind: MsgBoxKind::Error,
                                is_confirm: false,
                                focus_yes: true,
                            });
                            return Ok(());
                        }
                    }
                }
                KeyCode::Esc => {
                    self.active_popup = None;
                    return Ok(());
                }
                _ => {}
            },
            Popup::MsgBox { .. } => match key.code {
                KeyCode::Enter | KeyCode::Esc | KeyCode::Char('q') | KeyCode::Char('o') | KeyCode::Char('O') => {
                    self.active_popup = None;
                    return Ok(());
                }
                _ => {}
            },
        }

        self.active_popup = Some(popup);
        Ok(())
    }

    fn open_external_editor(&mut self) -> Result<(), String> {
        let editor_cmd = self
            .config
            .external_editor
            .command
            .clone()
            .or_else(|| std::env::var("EDITOR").ok())
            .unwrap_or_else(|| "vim".to_string());

        let temp_file = tempfile::Builder::new()
            .suffix(&format!(".{}", self.config.external_editor.temp_file_extension))
            .tempfile()
            .map_err(|e| format!("Failed to create temp file: {}", e))?;

        let temp_path = temp_file.path().to_path_buf();
        std::fs::write(&temp_path, self.editor.get_content())
            .map_err(|e| format!("Failed to write temp file: {}", e))?;

        let _ = std::process::Command::new(editor_cmd)
            .arg(&temp_path)
            .status();

        if let Ok(new_content) = std::fs::read_to_string(&temp_path) {
            self.editor.set_content(&new_content);
            self.save_current_editor_content()?;
        }

        Ok(())
    }
}

fn parse_date_str(s: &str) -> Option<DateTime<Utc>> {
    let parts: Vec<&str> = s.split('-').collect();
    if parts.len() == 3 {
        if let (Ok(d), Ok(m), Ok(y)) = (parts[0].parse::<u32>(), parts[1].parse::<u32>(), parts[2].parse::<i32>()) {
            if let Some(naive_date) = chrono::NaiveDate::from_ymd_opt(y, m, d) {
                if let Some(naive_dt) = naive_date.and_hms_opt(0, 0, 0) {
                    if let Some(local_dt) = Local.from_local_datetime(&naive_dt).single() {
                        return Some(local_dt.with_timezone(&Utc));
                    }
                }
            }
        }
    }
    None
}
EOF"}

actions.command:
cat <<'EOF' > src/app/mod.rs
pub mod editor;
pub mod popups;
pub mod ui;

use crate::backend::Backend;
use crate::config::Config;
use crate::model::{Entry, TransferData, TransferEntry};
use crate::theme::Theme;
use editor::{EditorMode, TextEditor};
use popups::{MsgBoxKind, Popup};
use chrono::{DateTime, Local, TimeZone, Utc};
use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};
use std::collections::HashSet;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Pane {
    Journals,
    Content,
}

pub struct FilterCriteria {
    pub matching_all: bool,
    pub title: String,
    pub content: String,
    pub priority: String,
    pub tags: Vec<String>,
}

pub struct SortCriteria {
    pub descending: bool,
    pub applied: Vec<String>,
}

impl Default for SortCriteria {
    fn default() -> Self {
        Self {
            descending: true,
            applied: vec!["Date".to_string(), "Priority".to_string()],
        }
    }
}

pub struct App {
    pub config: Config,
    pub theme: Theme,
    pub backend: Box<dyn Backend>,
    pub entries: Vec<Entry>,
    pub filtered_indices: Vec<usize>,
    pub selected_index: usize,
    pub focused_pane: Pane,
    pub is_multi_select: bool,
    pub multi_selected: HashSet<u32>,
    pub editor: TextEditor,
    pub active_popup: Option<Popup>,
    pub filter_criteria: Option<FilterCriteria>,
    pub sort_criteria: SortCriteria,
    pub should_quit: bool,
}

impl App {
    pub fn new(config: Config, theme: Theme, backend: Box<dyn Backend>) -> Result<Self, String> {
        let mut app = Self {
            config,
            theme,
            backend,
            entries: Vec::new(),
            filtered_indices: Vec::new(),
            selected_index: 0,
            focused_pane: Pane::Journals,
            is_multi_select: false,
            multi_selected: HashSet::new(),
            editor: TextEditor::new(),
            active_popup: None,
            filter_criteria: None,
            sort_criteria: SortCriteria::default(),
            should_quit: false,
        };
        app.reload_entries()?;
        Ok(app)
    }

    pub fn reload_entries(&mut self) -> Result<(), String> {
        self.entries = self.backend.get_entries()?;
        self.apply_filter_and_sort();
        self.sync_editor_content();
        Ok(())
    }

    pub fn apply_filter_and_sort(&mut self) {
        let mut indices: Vec<usize> = (0..self.entries.len()).collect();

        if let Some(ref filter) = self.filter_criteria {
            indices.retain(|&idx| {
                let entry = &self.entries[idx];
                let title_match = filter.title.is_empty()
                    || entry.title.to_lowercase().contains(&filter.title.to_lowercase());
                let content_match = filter.content.is_empty()
                    || entry.content.to_lowercase().contains(&filter.content.to_lowercase());
                let priority_match = filter.priority.is_empty() || {
                    if let Ok(p) = filter.priority.parse::<u32>() {
                        entry.priority == Some(p)
                    } else {
                        false
                    }
                };
                let tags_match = if filter.tags.is_empty() {
                    true
                } else if filter.matching_all {
                    filter.tags.iter().all(|t| entry.tags.contains(t))
                } else {
                    filter.tags.iter().any(|t| entry.tags.contains(t))
                };

                if filter.matching_all {
                    title_match && content_match && priority_match && tags_match
                } else {
                    title_match || content_match || priority_match || tags_match
                }
            });
        }

        indices.sort_by(|&a, &b| {
            let e1 = &self.entries[a];
            let e2 = &self.entries[b];

            for crit in &self.sort_criteria.applied {
                let cmp = match crit.as_str() {
                    "Date" => e1.date.cmp(&e2.date),
                    "Priority" => e1.priority.cmp(&e2.priority),
                    "Title" => e1.title.to_lowercase().cmp(&e2.title.to_lowercase()),
                    _ => std::cmp::Ordering::Equal,
                };
                if cmp != std::cmp::Ordering::Equal {
                    return if self.sort_criteria.descending {
                        cmp.reverse()
                    } else {
                        cmp
                    };
                }
            }
            std::cmp::Ordering::Equal
        });

        self.filtered_indices = indices;
        if self.selected_index >= self.filtered_indices.len() {
            self.selected_index = self.filtered_indices.len().saturating_sub(1);
        }
    }

    pub fn get_selected_entry(&self) -> Option<&Entry> {
        if self.filtered_indices.is_empty() {
            None
        } else {
            let idx = self.filtered_indices[self.selected_index];
            self.entries.get(idx)
        }
    }

    pub fn sync_editor_content(&mut self) {
        let content = self.get_selected_entry().map(|e| e.content.clone()).unwrap_or_default();
        self.editor.set_content(&content);
    }

    pub fn save_current_editor_content(&mut self) -> Result<(), String> {
        if let Some(entry) = self.get_selected_entry().cloned() {
            let new_content = self.editor.get_content();
            let updated = self.backend.update_entry(
                entry.id,
                entry.title,
                entry.date,
                entry.priority,
                entry.tags,
                new_content,
            )?;
            if let Some(e) = self.entries.iter_mut().find(|e| e.id == updated.id) {
                e.content = updated.content;
            }
            self.editor.is_dirty = false;
        }
        Ok(())
    }

    pub fn handle_key_event(&mut self, key: KeyEvent) -> Result<(), String> {
        if let Some(popup) = self.active_popup.clone() {
            self.handle_popup_key(key, popup)?;
            return Ok(());
        }

        if self.is_multi_select {
            self.handle_multi_select_key(key)?;
            return Ok(());
        }

        match self.focused_pane {
            Pane::Journals => self.handle_journals_pane_key(key)?,
            Pane::Content => self.handle_content_pane_key(key)?,
        }

        Ok(())
    }

    fn handle_journals_pane_key(&mut self, key: KeyEvent) -> Result<(), String> {
        match key.code {
            KeyCode::Char('q') => self.should_quit = true,
            KeyCode::Tab | KeyCode::BackTab => {
                self.focused_pane = Pane::Content;
            }
            KeyCode::Char('l') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                self.focused_pane = Pane::Content;
            }
            KeyCode::Char('j') | KeyCode::Down => {
                if !self.filtered_indices.is_empty()
                    && self.selected_index + 1 < self.filtered_indices.len()
                {
                    self.selected_index += 1;
                    self.sync_editor_content();
                }
            }
            KeyCode::Char('k') | KeyCode::Up => {
                if self.selected_index > 0 {
                    self.selected_index -= 1;
                    self.sync_editor_content();
                }
            }
            KeyCode::PageDown => {
                if !self.filtered_indices.is_empty() {
                    self.selected_index = (self.selected_index + self.config.scroll_per_page)
                        .min(self.filtered_indices.len() - 1);
                    self.sync_editor_content();
                }
            }
            KeyCode::PageUp => {
                self.selected_index = self
                    .selected_index
                    .saturating_sub(self.config.scroll_per_page);
                self.sync_editor_content();
            }
            KeyCode::Char('d') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                if !self.filtered_indices.is_empty() {
                    self.selected_index = (self.selected_index + self.config.scroll_per_page)
                        .min(self.filtered_indices.len() - 1);
                    self.sync_editor_content();
                }
            }
            KeyCode::Char('u') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                self.selected_index = self
                    .selected_index
                    .saturating_sub(self.config.scroll_per_page);
                self.sync_editor_content();
            }
            KeyCode::Home | KeyCode::Char('g') => {
                self.selected_index = 0;
                self.sync_editor_content();
            }
            KeyCode::End | KeyCode::Char('G') => {
                if !self.filtered_indices.is_empty() {
                    self.selected_index = self.filtered_indices.len() - 1;
                    self.sync_editor_content();
                }
            }
            KeyCode::Enter => {
                self.focused_pane = Pane::Content;
                self.editor.mode = EditorMode::Insert;
            }
            KeyCode::Char('m') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                self.focused_pane = Pane::Content;
                self.editor.mode = EditorMode::Insert;
            }
            KeyCode::Char('n') => {
                let today = Local::now().format("%d-%m-%Y").to_string();
                self.active_popup = Some(Popup::CreateEntry {
                    title: String::new(),
                    date_str: today,
                    priority: String::new(),
                    tags_str: String::new(),
                    focus: 0,
                });
            }
            KeyCode::Char('e') if key.modifiers.contains(KeyModifiers::ALT) || key.modifiers.contains(KeyModifiers::CONTROL) => {
                self.open_external_editor()?;
            }
            KeyCode::Char('e') => {
                if let Some(entry) = self.get_selected_entry() {
                    let date_str = entry.date.with_timezone(&Local).format("%d-%m-%Y").to_string();
                    let prio_str = entry.priority.map(|p| p.to_string()).unwrap_or_default();
                    let tags_str = entry.tags.join(", ");
                    self.active_popup = Some(Popup::EditEntry {
                        id: entry.id,
                        title: entry.title.clone(),
                        date_str,
                        priority: prio_str,
                        tags_str,
                        focus: 0,
                    });
                }
            }
            KeyCode::Char('d') | KeyCode::Delete => {
                if self.get_selected_entry().is_some() {
                    self.active_popup = Some(Popup::DeleteEntry {
                        is_multi: false,
                        count: 1,
                        focus_yes: true,
                    });
                }
            }
            KeyCode::Char('v') => {
                self.is_multi_select = true;
            }
            KeyCode::Char('f') => {
                let mut all_tags = HashSet::new();
                for e in &self.entries {
                    for t in &e.tags {
                        all_tags.insert(t.clone());
                    }
                }
                let mut sorted_tags: Vec<String> = all_tags.into_iter().collect();
                sorted_tags.sort();

                let (m_all, t, c, p, sel_t) = if let Some(ref filter) = self.filter_criteria {
                    (
                        filter.matching_all,
                        filter.title.clone(),
                        filter.content.clone(),
                        filter.priority.clone(),
                        filter.tags.clone(),
                    )
                } else {
                    (true, String::new(), String::new(), String::new(), Vec::new())
                };

                self.active_popup = Some(Popup::Filter {
                    matching_all: m_all,
                    title: t,
                    content: c,
                    priority: p,
                    all_tags: sorted_tags,
                    selected_tags: sel_t,
                    focus: 0,
                    tag_list_index: 0,
                });
            }
            KeyCode::Char('o') => {
                let all_crits = vec!["Date".to_string(), "Priority".to_string(), "Title".to_string()];
                let avail: Vec<String> = all_crits
                    .into_iter()
                    .filter(|c| !self.sort_criteria.applied.contains(c))
                    .collect();

                self.active_popup = Some(Popup::Sort {
                    descending: self.sort_criteria.descending,
                    available: avail,
                    applied: self.sort_criteria.applied.clone(),
                    focus: 0,
                    avail_index: 0,
                    applied_index: 0,
                });
            }
            KeyCode::Char('?') => {
                self.active_popup = Some(Popup::Help { tab: 0, scroll: 0 });
            }
            KeyCode::Char('>') => {
                if let Some(entry) = self.get_selected_entry() {
                    let default_path = format!("/workspace/{}.txt", entry.title);
                    self.active_popup = Some(Popup::ExportSingle {
                        id: entry.id,
                        title: entry.title.clone(),
                        path_str: default_path,
                    });
                }
            }
            KeyCode::Char('<') => {
                self.active_popup = Some(Popup::Import {
                    path_str: "/workspace/tjournal_export.json".to_string(),
                });
            }
            KeyCode::Char('r') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                self.reload_entries()?;
            }
            _ => {}
        }
        Ok(())
    }

    fn handle_content_pane_key(&mut self, key: KeyEvent) -> Result<(), String> {
        match self.editor.mode {
            EditorMode::Normal => match key.code {
                KeyCode::Char('q') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.sync_editor_content();
                }
                KeyCode::Char('q') => self.should_quit = true,
                KeyCode::Tab | KeyCode::BackTab => {
                    self.focused_pane = Pane::Journals;
                }
                KeyCode::Char('h') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.focused_pane = Pane::Journals;
                }
                KeyCode::Char('s') if key.modifiers.contains(KeyModifiers::CONTROL) || key.code == KeyCode::Char('s') => {
                    self.save_current_editor_content()?;
                }
                KeyCode::Char('i') => {
                    self.editor.mode = EditorMode::Insert;
                }
                KeyCode::Char('I') => {
                    self.editor.cursor_col = 0;
                    self.editor.mode = EditorMode::Insert;
                }
                KeyCode::Char('a') => {
                    let len = self.editor.line_len();
                    self.editor.cursor_col = (self.editor.cursor_col + 1).min(len);
                    self.editor.mode = EditorMode::Insert;
                }
                KeyCode::Char('A') => {
                    self.editor.cursor_col = self.editor.line_len();
                    self.editor.mode = EditorMode::Insert;
                }
                KeyCode::Char('o') => {
                    self.editor.insert_newline();
                    self.editor.mode = EditorMode::Insert;
                }
                KeyCode::Char('O') => {
                    if self.editor.cursor_row > 0 {
                        self.editor.cursor_row -= 1;
                    }
                    self.editor.insert_newline();
                    self.editor.mode = EditorMode::Insert;
                }
                KeyCode::Char('v') => {
                    self.editor.mode = EditorMode::Visual;
                    self.editor.selection_anchor = Some((self.editor.cursor_row, self.editor.cursor_col));
                }
                KeyCode::Char('h') | KeyCode::Left => {
                    self.editor.cursor_col = self.editor.cursor_col.saturating_sub(1);
                }
                KeyCode::Char('l') | KeyCode::Right => {
                    self.editor.cursor_col = (self.editor.cursor_col + 1).min(self.editor.line_len());
                }
                KeyCode::Char('k') | KeyCode::Up => {
                    self.editor.cursor_row = self.editor.cursor_row.saturating_sub(1);
                    self.editor.fix_col();
                }
                KeyCode::Char('j') | KeyCode::Down => {
                    self.editor.cursor_row = (self.editor.cursor_row + 1).min(self.editor.lines.len() - 1);
                    self.editor.fix_col();
                }
                KeyCode::Char('0') | KeyCode::Home => {
                    self.editor.cursor_col = 0;
                }
                KeyCode::Char('$') | KeyCode::End => {
                    self.editor.cursor_col = self.editor.line_len();
                }
                KeyCode::Char('g') => {
                    self.editor.cursor_row = 0;
                    self.editor.cursor_col = 0;
                }
                KeyCode::Char('G') => {
                    self.editor.cursor_row = self.editor.lines.len() - 1;
                    self.editor.cursor_col = 0;
                }
                KeyCode::Char('x') => {
                    self.editor.delete_char();
                }
                KeyCode::Char('e') if key.modifiers.contains(KeyModifiers::ALT) || key.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.open_external_editor()?;
                }
                KeyCode::Char('?') => {
                    self.active_popup = Some(Popup::Help { tab: 1, scroll: 0 });
                }
                _ => {}
            },
            EditorMode::Insert => match key.code {
                KeyCode::Esc | KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) || key.code == KeyCode::Esc => {
                    self.editor.mode = EditorMode::Normal;
                }
                KeyCode::Enter => {
                    self.editor.insert_newline();
                }
                KeyCode::Backspace => {
                    self.editor.backspace();
                }
                KeyCode::Delete => {
                    self.editor.delete_char();
                }
                KeyCode::Char('d') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.editor.delete_char();
                }
                KeyCode::Char('h') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.editor.backspace();
                }
                KeyCode::Char('k') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.editor.delete_to_end_of_line();
                }
                KeyCode::Char('a') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.editor.cursor_col = 0;
                }
                KeyCode::Char('e') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.editor.cursor_col = self.editor.line_len();
                }
                KeyCode::Char('f') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.editor.cursor_col = (self.editor.cursor_col + 1).min(self.editor.line_len());
                }
                KeyCode::Char('b') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.editor.cursor_col = self.editor.cursor_col.saturating_sub(1);
                }
                KeyCode::Char('n') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.editor.cursor_row = (self.editor.cursor_row + 1).min(self.editor.lines.len() - 1);
                    self.editor.fix_col();
                }
                KeyCode::Char('p') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.editor.cursor_row = self.editor.cursor_row.saturating_sub(1);
                    self.editor.fix_col();
                }
                KeyCode::Char(c) => {
                    self.editor.insert_char(c);
                }
                _ => {}
            },
            EditorMode::Visual => match key.code {
