use super::Backend;
use crate::model::{Entry, TransferEntry};
use chrono::{DateTime, Utc};
use std::ffi::{CStr, CString};
use std::os::raw::{c_char, c_int, c_void};
use std::path::PathBuf;

#[link(name = "sqlite3")]
extern "C" {
    fn sqlite3_open(filename: *const c_char, ppDb: *mut *mut c_void) -> c_int;
    fn sqlite3_close(db: *mut c_void) -> c_int;
    fn sqlite3_exec(
        db: *mut c_void,
        sql: *const c_char,
        callback: Option<extern "C" fn(*mut c_void, c_int, *mut *mut c_char, *mut *mut c_char) -> c_int>,
        arg: *mut c_void,
        errmsg: *mut *mut c_char,
    ) -> c_int;
    fn sqlite3_errmsg(db: *mut c_void) -> *const c_char;
    fn sqlite3_last_insert_rowid(db: *mut c_void) -> i64;
    fn sqlite3_prepare_v2(
        db: *mut c_void,
        zSql: *const c_char,
        nByte: c_int,
        ppStmt: *mut *mut c_void,
        pzTail: *mut *const c_char,
    ) -> c_int;
    fn sqlite3_step(stmt: *mut c_void) -> c_int;
    fn sqlite3_column_int(stmt: *mut c_void, iCol: c_int) -> c_int;
    fn sqlite3_column_text(stmt: *mut c_void, iCol: c_int) -> *const u8;
    fn sqlite3_column_type(stmt: *mut c_void, iCol: c_int) -> c_int;
    fn sqlite3_bind_int(stmt: *mut c_void, iCol: c_int, iValue: c_int) -> c_int;
    fn sqlite3_bind_text(
        stmt: *mut c_void,
        iCol: c_int,
        zData: *const c_char,
        nData: c_int,
        xDel: Option<extern "C" fn(*mut c_void)>,
    ) -> c_int;
    fn sqlite3_bind_null(stmt: *mut c_void, iCol: c_int) -> c_int;
    fn sqlite3_finalize(stmt: *mut c_void) -> c_int;
}

const SQLITE_OK: c_int = 0;
const SQLITE_ROW: c_int = 100;
const SQLITE_DONE: c_int = 101;
const SQLITE_NULL: c_int = 5;

pub struct SqliteBackend {
    _file_path: PathBuf,
    db: *mut c_void,
}

unsafe impl Send for SqliteBackend {}
unsafe impl Sync for SqliteBackend {}

impl SqliteBackend {
    pub fn new(file_path: PathBuf) -> Result<Self, String> {
        if let Some(parent) = file_path.parent() {
            let _ = std::fs::create_dir_all(parent);
        }
        let c_path = CString::new(file_path.to_str().ok_or("Invalid DB path")?).map_err(|e| e.to_string())?;
        let mut db: *mut c_void = std::ptr::null_mut();
        unsafe {
            let rc = sqlite3_open(c_path.as_ptr(), &mut db);
            if rc != SQLITE_OK {
                let err = CStr::from_ptr(sqlite3_errmsg(db)).to_string_lossy().to_string();
                return Err(format!("Failed to open SQLite database: {}", err));
            }
        }

        let mut backend = Self { _file_path: file_path, db };
        backend.init_tables()?;
        Ok(backend)
    }

    fn exec(&self, sql: &str) -> Result<(), String> {
        let c_sql = CString::new(sql).map_err(|e| e.to_string())?;
        unsafe {
            let rc = sqlite3_exec(self.db, c_sql.as_ptr(), None, std::ptr::null_mut(), std::ptr::null_mut());
            if rc != SQLITE_OK {
                let err = CStr::from_ptr(sqlite3_errmsg(self.db)).to_string_lossy().to_string();
                return Err(err);
            }
        }
        Ok(())
    }

    fn init_tables(&mut self) -> Result<(), String> {
        self.exec("PRAGMA journal_mode = WAL; PRAGMA foreign_keys = ON;")?;

        self.exec(
            "CREATE TABLE IF NOT EXISTS _sqlx_migrations (
                version BIGINT PRIMARY KEY,
                description TEXT NOT NULL,
                installed_on TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
                success BOOLEAN NOT NULL,
                checksum BLOB NOT NULL,
                execution_time BIGINT NOT NULL
            );",
        )?;

        self.exec(
            "CREATE TABLE IF NOT EXISTS entries (
                id INTEGER PRIMARY KEY NOT NULL,
                title TEXT NOT NULL,
                date DATE NOT NULL,
                content TEXT
            );",
        )?;

        self.exec(
            "CREATE TABLE IF NOT EXISTS tags (
                entry_id INTEGER NOT NULL,
                tag TEXT NOT NULL,
                PRIMARY KEY (entry_id, tag),
                FOREIGN KEY (entry_id) REFERENCES entries (id) ON DELETE CASCADE
            );",
        )?;

        let _ = self.exec("ALTER TABLE entries ADD COLUMN priority INTEGER DEFAULT NULL;");

        let _ = self.exec("INSERT OR IGNORE INTO _sqlx_migrations (version, description, success, checksum, execution_time) VALUES (20230509041613, 'init entries', 1, X'a9b962e074e56db0fbfbcf4874ed6d1e8d94313c9c0122247465cc26057ad3635235b208703db8a0843a8bc16cd50685', 100);");
        let _ = self.exec("INSERT OR IGNORE INTO _sqlx_migrations (version, description, success, checksum, execution_time) VALUES (20230613041405, 'add tags', 1, X'e0eb5fd4d092c82cb2bd4528ce27fe9c037f045245ac9f1235ee2cef07c75443e8fec98c3a5f0562c641b1bc5301f319', 100);");
        let _ = self.exec("INSERT OR IGNORE INTO _sqlx_migrations (version, description, success, checksum, execution_time) VALUES (20240104160740, 'entries priorities', 1, X'4dc4e4c3a2cd7adf8ca6ee6cca5a84eaa929bbb9c4969af5bc181a992095e61aa156dab76718437fccd99e7fa1a75f7c', 100);");

        Ok(())
    }

    fn insert_tags(&self, entry_id: u32, tags: &[String]) -> Result<(), String> {
        let delete_sql = CString::new("DELETE FROM tags WHERE entry_id = ?;").unwrap();
        unsafe {
            let mut stmt: *mut c_void = std::ptr::null_mut();
            if sqlite3_prepare_v2(self.db, delete_sql.as_ptr(), -1, &mut stmt, std::ptr::null_mut()) == SQLITE_OK {
                sqlite3_bind_int(stmt, 1, entry_id as c_int);
                sqlite3_step(stmt);
                sqlite3_finalize(stmt);
            }
        }

        let insert_sql = CString::new("INSERT OR IGNORE INTO tags (entry_id, tag) VALUES (?, ?);").unwrap();
        for tag in tags {
            if tag.trim().is_empty() { continue; }
            unsafe {
                let mut stmt: *mut c_void = std::ptr::null_mut();
                if sqlite3_prepare_v2(self.db, insert_sql.as_ptr(), -1, &mut stmt, std::ptr::null_mut()) == SQLITE_OK {
                    sqlite3_bind_int(stmt, 1, entry_id as c_int);
                    let c_tag = CString::new(tag.as_str()).unwrap();
                    sqlite3_bind_text(stmt, 2, c_tag.as_ptr(), -1, None);
                    sqlite3_step(stmt);
                    sqlite3_finalize(stmt);
                }
            }
        }
        Ok(())
    }
}

impl Drop for SqliteBackend {
    fn drop(&mut self) {
        if !self.db.is_null() {
            unsafe {
                sqlite3_close(self.db);
            }
        }
    }
}

impl Backend for SqliteBackend {
    fn get_entries(&self) -> Result<Vec<Entry>, String> {
        let sql = CString::new(
            "SELECT entries.id, entries.title, entries.date, entries.content, entries.priority, GROUP_CONCAT(tags.tag, ',') AS tags
             FROM entries
             LEFT JOIN tags ON entries.id = tags.entry_id
             GROUP BY entries.id
             ORDER BY date DESC;"
        ).unwrap();

        let mut entries = Vec::new();
        unsafe {
            let mut stmt: *mut c_void = std::ptr::null_mut();
            if sqlite3_prepare_v2(self.db, sql.as_ptr(), -1, &mut stmt, std::ptr::null_mut()) != SQLITE_OK {
                let err = CStr::from_ptr(sqlite3_errmsg(self.db)).to_string_lossy().to_string();
                return Err(err);
            }

            while sqlite3_step(stmt) == SQLITE_ROW {
                let id = sqlite3_column_int(stmt, 0) as u32;
                let title_ptr = sqlite3_column_text(stmt, 1);
                let title = if !title_ptr.is_null() {
                    CStr::from_ptr(title_ptr as *const c_char).to_string_lossy().to_string()
                } else {
                    String::new()
                };

                let date_ptr = sqlite3_column_text(stmt, 2);
                let date_str = if !date_ptr.is_null() {
                    CStr::from_ptr(date_ptr as *const c_char).to_string_lossy().to_string()
                } else {
                    String::new()
                };

                let content_ptr = sqlite3_column_text(stmt, 3);
                let content = if !content_ptr.is_null() {
                    CStr::from_ptr(content_ptr as *const c_char).to_string_lossy().to_string()
                } else {
                    String::new()
                };

                let priority = if sqlite3_column_type(stmt, 4) != SQLITE_NULL {
                    Some(sqlite3_column_int(stmt, 4) as u32)
                } else {
                    None
                };

                let tags_ptr = sqlite3_column_text(stmt, 5);
                let tags = if !tags_ptr.is_null() {
                    let s = CStr::from_ptr(tags_ptr as *const c_char).to_string_lossy().to_string();
                    s.split(',').map(|t| t.trim().to_string()).filter(|t| !t.is_empty()).collect()
                } else {
                    Vec::new()
                };

                let date = DateTime::parse_from_rfc3339(&date_str)
                    .map(|dt| dt.with_timezone(&Utc))
                    .unwrap_or_else(|_| Utc::now());

                entries.push(Entry {
                    id,
                    date,
                    title,
                    content,
                    tags,
                    priority,
                });
            }

            sqlite3_finalize(stmt);
        }

        Ok(entries)
    }

    fn add_entry(
        &mut self,
        title: String,
        date: DateTime<Utc>,
        priority: Option<u32>,
        tags: Vec<String>,
    ) -> Result<Entry, String> {
        let sql = CString::new("INSERT INTO entries (title, date, content, priority) VALUES (?, ?, '', ?);").unwrap();
        let id: u32;
        unsafe {
            let mut stmt: *mut c_void = std::ptr::null_mut();
            if sqlite3_prepare_v2(self.db, sql.as_ptr(), -1, &mut stmt, std::ptr::null_mut()) != SQLITE_OK {
                let err = CStr::from_ptr(sqlite3_errmsg(self.db)).to_string_lossy().to_string();
                return Err(err);
            }

            let c_title = CString::new(title.as_str()).unwrap();
            sqlite3_bind_text(stmt, 1, c_title.as_ptr(), -1, None);

            let date_str = date.to_rfc3339();
            let c_date = CString::new(date_str.as_str()).unwrap();
            sqlite3_bind_text(stmt, 2, c_date.as_ptr(), -1, None);

            if let Some(p) = priority {
                sqlite3_bind_int(stmt, 3, p as c_int);
            } else {
                sqlite3_bind_null(stmt, 3);
            }

            if sqlite3_step(stmt) != SQLITE_DONE {
                let err = CStr::from_ptr(sqlite3_errmsg(self.db)).to_string_lossy().to_string();
                sqlite3_finalize(stmt);
                return Err(err);
            }
            sqlite3_finalize(stmt);

            id = sqlite3_last_insert_rowid(self.db) as u32;
        }

        self.insert_tags(id, &tags)?;

        Ok(Entry {
            id,
            date,
            title,
            content: String::new(),
            tags,
            priority,
        })
    }

    fn update_entry(
        &mut self,
        id: u32,
        title: String,
        date: DateTime<Utc>,
        priority: Option<u32>,
        tags: Vec<String>,
        content: String,
    ) -> Result<Entry, String> {
        let sql = CString::new("UPDATE entries SET title = ?, date = ?, priority = ?, content = ? WHERE id = ?;").unwrap();
        unsafe {
            let mut stmt: *mut c_void = std::ptr::null_mut();
            if sqlite3_prepare_v2(self.db, sql.as_ptr(), -1, &mut stmt, std::ptr::null_mut()) != SQLITE_OK {
                let err = CStr::from_ptr(sqlite3_errmsg(self.db)).to_string_lossy().to_string();
                return Err(err);
            }

            let c_title = CString::new(title.as_str()).unwrap();
            sqlite3_bind_text(stmt, 1, c_title.as_ptr(), -1, None);

            let date_str = date.to_rfc3339();
            let c_date = CString::new(date_str.as_str()).unwrap();
            sqlite3_bind_text(stmt, 2, c_date.as_ptr(), -1, None);

            if let Some(p) = priority {
                sqlite3_bind_int(stmt, 3, p as c_int);
            } else {
                sqlite3_bind_null(stmt, 3);
            }

            let c_content = CString::new(content.as_str()).unwrap();
            sqlite3_bind_text(stmt, 4, c_content.as_ptr(), -1, None);

            sqlite3_bind_int(stmt, 5, id as c_int);

            if sqlite3_step(stmt) != SQLITE_DONE {
                let err = CStr::from_ptr(sqlite3_errmsg(self.db)).to_string_lossy().to_string();
                sqlite3_finalize(stmt);
                return Err(err);
            }
            sqlite3_finalize(stmt);
        }

        self.insert_tags(id, &tags)?;

        Ok(Entry {
            id,
            date,
            title,
            content,
            tags,
            priority,
        })
    }

    fn delete_entry(&mut self, id: u32) -> Result<(), String> {
