    fn get_entries(&self) -> Result<Vec<Entry>, String> {
        let sql = CString::new(
            "SELECT entries.id, entries.title, entries.date, entries.content, entries.priority, GROUP_CONCAT(tags.tag, ',') AS tags
             FROM entries
             LEFT JOIN tags ON entries.id = tags.entry_id
             GROUP BY entries.id
             ORDER BY date DESC;"
        ).unwrap();

        let mut entries = Vec::new();
        unsafe {
            let mut stmt: *mut c_void = std::ptr::null_mut();
            if sqlite3_prepare_v2(self.db, sql.as_ptr(), -1, &mut stmt, std::ptr::null_mut()) != SQLITE_OK {
                let err = CStr::from_ptr(sqlite3_errmsg(self.db)).to_string_lossy().to_string();
                return Err(err);
            }

            while sqlite3_step(stmt) == SQLITE_ROW {
                let id = sqlite3_column_int(stmt, 0) as u32;
                let title_ptr = sqlite3_column_text(stmt, 1);
                let title = if !title_ptr.is_null() {
                    CStr::from_ptr(title_ptr as *const c_char).to_string_lossy().to_string()
                } else {
                    String::new()
                };

                let date_ptr = sqlite3_column_text(stmt, 2);
                let date_str = if !date_ptr.is_null() {
                    CStr::from_ptr(date_ptr as *const c_char).to_string_lossy().to_string()
                } else {
                    String::new()
                };

                let content_ptr = sqlite3_column_text(stmt, 3);
                let content = if !content_ptr.is_null() {
                    CStr::from_ptr(content_ptr as *const c_char).to_string_lossy().to_string()
                } else {
                    String::new()
                };

                let priority = if sqlite3_column_type(stmt, 4) != SQLITE_NULL {
                    Some(sqlite3_column_int(stmt, 4) as u32)
                } else {
                    None
                };

                let tags_ptr = sqlite3_column_text(stmt, 5);
                let tags = if !tags_ptr.is_null() {
                    let s = CStr::from_ptr(tags_ptr as *const c_char).to_string_lossy().to_string();
                    s.split(',').map(|t| t.trim().to_string()).filter(|t| !t.is_empty()).collect()
                } else {
                    Vec::new()
                };

                let date = DateTime::parse_from_rfc3339(&date_str)
                    .map(|dt| dt.with_timezone(&Utc))
                    .unwrap_or_else(|_| Utc::now());

                entries.push(Entry {
                    id,
                    date,
                    title,
                    content,
                    tags,
                    priority,
                });
            }

            sqlite3_finalize(stmt);
        }

        Ok(entries)
    }

    fn add_entry(
        &mut self,
        title: String,
        date: DateTime<Utc>,
        priority: Option<u32>,
        tags: Vec<String>,
    ) -> Result<Entry, String> {
        let sql = CString::new("INSERT INTO entries (title, date, content, priority) VALUES (?, ?, '', ?);").unwrap();
        let id: u32;
        unsafe {
            let mut stmt: *mut c_void = std::ptr::null_mut();
            if sqlite3_prepare_v2(self.db, sql.as_ptr(), -1, &mut stmt, std::ptr::null_mut()) != SQLITE_OK {
                let err = CStr::from_ptr(sqlite3_errmsg(self.db)).to_string_lossy().to_string();
                return Err(err);
            }

            let c_title = CString::new(title.as_str()).unwrap();
            sqlite3_bind_text(stmt, 1, c_title.as_ptr(), -1, None);

            let date_str = date.to_rfc3339();
            let c_date = CString::new(date_str.as_str()).unwrap();
            sqlite3_bind_text(stmt, 2, c_date.as_ptr(), -1, None);

            if let Some(p) = priority {
                sqlite3_bind_int(stmt, 3, p as c_int);
            } else {
                sqlite3_bind_null(stmt, 3);
            }

            if sqlite3_step(stmt) != SQLITE_DONE {
                let err = CStr::from_ptr(sqlite3_errmsg(self.db)).to_string_lossy().to_string();
                sqlite3_finalize(stmt);
                return Err(err);
            }
            sqlite3_finalize(stmt);

            id = sqlite3_last_insert_rowid(self.db) as u32;
        }

        self.insert_tags(id, &tags)?;

        Ok(Entry {
            id,
            date,
            title,
            content: String::new(),
            tags,
            priority,
        })
    }

    fn update_entry(
        &mut self,
        id: u32,
        title: String,
        date: DateTime<Utc>,
        priority: Option<u32>,
        tags: Vec<String>,
        content: String,
    ) -> Result<Entry, String> {
        let sql = CString::new("UPDATE entries SET title = ?, date = ?, priority = ?, content = ? WHERE id = ?;").unwrap();
        unsafe {
            let mut stmt: *mut c_void = std::ptr::null_mut();
            if sqlite3_prepare_v2(self.db, sql.as_ptr(), -1, &mut stmt, std::ptr::null_mut()) != SQLITE_OK {
                let err = CStr::from_ptr(sqlite3_errmsg(self.db)).to_string_lossy().to_string();
                return Err(err);
            }

            let c_title = CString::new(title.as_str()).unwrap();
            sqlite3_bind_text(stmt, 1, c_title.as_ptr(), -1, None);

            let date_str = date.to_rfc3339();
            let c_date = CString::new(date_str.as_str()).unwrap();
            sqlite3_bind_text(stmt, 2, c_date.as_ptr(), -1, None);

            if let Some(p) = priority {
                sqlite3_bind_int(stmt, 3, p as c_int);
            } else {
                sqlite3_bind_null(stmt, 3);
            }

            let c_content = CString::new(content.as_str()).unwrap();
            sqlite3_bind_text(stmt, 4, c_content.as_ptr(), -1, None);

            sqlite3_bind_int(stmt, 5, id as c_int);

            if sqlite3_step(stmt) != SQLITE_DONE {
                let err = CStr::from_ptr(sqlite3_errmsg(self.db)).to_string_lossy().to_string();
                sqlite3_finalize(stmt);
                return Err(err);
            }
            sqlite3_finalize(stmt);
        }

        self.insert_tags(id, &tags)?;

        Ok(Entry {
            id,
            date,
            title,
            content,
            tags,
            priority,
        })
    }

    fn delete_entry(&mut self, id: u32) -> Result<(), String> {
        let sql = CString::new("DELETE FROM entries WHERE id = ?;").unwrap();
        unsafe {
            let mut stmt: *mut c_void = std::ptr::null_mut();
            if sqlite3_prepare_v2(self.db, sql.as_ptr(), -1, &mut stmt, std::ptr::null_mut()) == SQLITE_OK {
                sqlite3_bind_int(stmt, 1, id as c_int);
                sqlite3_step(stmt);
                sqlite3_finalize(stmt);
            }
        }
        Ok(())
    }

    fn delete_entries(&mut self, ids: &[u32]) -> Result<(), String> {
        for &id in ids {
            self.delete_entry(id)?;
        }
        Ok(())
    }

    fn assign_priority(&mut self, priority: u32) -> Result<(), String> {
        let sql = CString::new("UPDATE entries SET priority = ? WHERE priority IS NULL;").unwrap();
        unsafe {
            let mut stmt: *mut c_void = std::ptr::null_mut();
            if sqlite3_prepare_v2(self.db, sql.as_ptr(), -1, &mut stmt, std::ptr::null_mut()) == SQLITE_OK {
                sqlite3_bind_int(stmt, 1, priority as c_int);
                sqlite3_step(stmt);
                sqlite3_finalize(stmt);
            }
        }
        Ok(())
    }

    fn import_entries(&mut self, entries: &[TransferEntry]) -> Result<(), String> {
        for te in entries {
            let added = self.add_entry(te.title.clone(), te.date, te.priority, te.tags.clone())?;
            self.update_entry(added.id, added.title, added.date, added.priority, added.tags, te.content.clone())?;
        }
        Ok(())
    }
}
